517:         final OneShotLatch latch = new OneShotLatch();
518:         final List<CheckedThread> threads = new ArrayList<>();
519:         for (int x = 0; x < numThreads; x++) {
520:             final CheckedThread thread =
521:                     new CheckedThread() {
522:                         @Override
523:                         public void go() {
524:                             final StreamExecutionEnvironment preparedEnvironment =
525:                                     new StreamExecutionEnvironment();
526:                             StreamExecutionEnvironment.initializeContextEnvironment(
527:                                     configuration -> preparedEnvironment);
528:                             try {
529:                                 waitingThreadCount.countDown();
530:                                 latch.awaitQuietly();
531:                                 assertThat(StreamExecutionEnvironment.getExecutionEnvironment())
532:                                         .isSameAs(preparedEnvironment);
533:                             } finally {
534:                                 StreamExecutionEnvironment.resetContextEnvironment();
535:                             }
536:                         }
537:                     };
538:             thread.start();
