337:     private InputChannel createInputChannel(
338:             SingleInputGate inputGate,
339:             int index,
340:             int buffersPerChannel,
341:             ShuffleDescriptor shuffleDescriptor,
342:             ResultSubpartitionIndexSet subpartitionIndexSet,
343:             ChannelStatistics channelStatistics,
344:             InputChannelMetrics metrics) {
345:         return applyWithShuffleTypeCheck(
346:                 NettyShuffleDescriptor.class,
347:                 shuffleDescriptor,
348:                 unknownShuffleDescriptor -> {
349:                     channelStatistics.numUnknownChannels++;
350:                     return new UnknownInputChannel(
351:                             inputGate,
352:                             index,
353:                             unknownShuffleDescriptor.getResultPartitionID(),
354:                             subpartitionIndexSet,
355:                             partitionManager,
