357:                             connectionManager,
358:                             partitionRequestInitialBackoff,
359:                             partitionRequestMaxBackoff,
360:                             partitionRequestListenerTimeout,
361:                             buffersPerChannel,
362:                             metrics);
363:                 },
364:                 nettyShuffleDescriptor ->
365:                         createKnownInputChannel(
366:                                 inputGate,
367:                                 index,
368:                                 buffersPerChannel,
369:                                 nettyShuffleDescriptor,
370:                                 subpartitionIndexSet,
371:                                 channelStatistics,
372:                                 metrics));
373:     }
