385:     public int getEstimatedRequestedSegmentsUsage() {
386:         int totalNumberOfMemorySegments = getTotalNumberOfMemorySegments();
387:         return totalNumberOfMemorySegments == 0
388:                 ? 0
389:                 : Math.toIntExact(
390:                         100L
391:                                 * getEstimatedNumberOfRequestedMemorySegments()
392:                                 / totalNumberOfMemorySegments);
