658:                 localBufferPools.add(localPool);
659:                 assertThat(localPool.getAvailableFuture()).isDone();
660:             }
661: 
662:             // request some segments from the global pool in two different ways
663:             final List<MemorySegment> segments = new ArrayList<>(numberOfSegmentsToRequest - 1);
664:             for (int i = 0; i < numberOfSegmentsToRequest - 1; ++i) {
665:                 segments.add(globalPool.requestPooledMemorySegment());
666:             }
667:             final List<MemorySegment> exclusiveSegments =
668:                     globalPool.requestUnpooledMemorySegments(
669:                             globalPool.getNumberOfAvailableMemorySegments() - 1);
670:             assertThat(globalPool.getAvailableFuture()).isDone();
671:             for (final BufferPool localPool : localBufferPools) {
672:                 assertThat(localPool.getAvailableFuture()).isDone();
673:             }
674: 
675:             // blocking request buffers form local buffer pools
676:             final CountDownLatch latch = new CountDownLatch(numLocalBufferPool);
677:             final BlockingQueue<BufferBuilder> segmentsRequested =
678:                     new ArrayBlockingQueue<>(numBuffers);
679:             final AtomicReference<Throwable> cause = new AtomicReference<>();
680:             for (final BufferPool localPool : localBufferPools) {
681:                 executorService.submit(
682:                         () -> {
683:                             try {
684:                                 for (int num = localPoolMaxSize; num > 0; --num) {
685:                                     segmentsRequested.add(localPool.requestBufferBuilderBlocking());
686:                                 }
687:                             } catch (Exception e) {
688:                                 cause.set(e);
689:                             } finally {
690:                                 latch.countDown();
691:                             }
692:                         });
693:             }
694: 
695:             // wait until all available buffers are requested
696:             while (segmentsRequested.size() + segments.size() + exclusiveSegments.size()
697:                     < numBuffers) {
