699:                 assertThat(cause.get()).isNull();
700:             }
701: 
702:             final CompletableFuture<?> globalPoolAvailableFuture = globalPool.getAvailableFuture();
703:             assertThat(globalPoolAvailableFuture).isNotDone();
704: 
705:             final List<CompletableFuture<?>> localPoolAvailableFutures =
706:                     new ArrayList<>(numLocalBufferPool);
707:             for (BufferPool localPool : localBufferPools) {
708:                 CompletableFuture<?> localPoolAvailableFuture = localPool.getAvailableFuture();
709:                 localPoolAvailableFutures.add(localPoolAvailableFuture);
710:                 assertThat(localPoolAvailableFuture).isNotDone();
711:             }
712: 
713:             // recycle the previously requested segments
714:             for (MemorySegment segment : segments) {
715:                 globalPool.recyclePooledMemorySegment(segment);
716:             }
717:             globalPool.recycleUnpooledMemorySegments(exclusiveSegments);
718: 
719:             assertThat(globalPoolAvailableFuture).isDone();
720:             for (CompletableFuture<?> localPoolAvailableFuture : localPoolAvailableFutures) {
721:                 assertThat(localPoolAvailableFuture).isDone();
722:             }
723: 
724:             // wait until all blocking buffer requests finish
725:             latch.await();
726: 
