640:     @Test
641:     void testBlockingRequestFromMultiLocalBufferPool() throws IOException, InterruptedException {
642:         final int localPoolRequiredSize = 5;
643:         final int localPoolMaxSize = 10;
644:         final int numLocalBufferPool = 2;
645:         final int numberOfSegmentsToRequest = 10;
646:         final int numBuffers = numLocalBufferPool * localPoolMaxSize;
647: 
648:         final ExecutorService executorService = Executors.newFixedThreadPool(numLocalBufferPool);
649:         final NetworkBufferPool globalPool = new NetworkBufferPool(numBuffers, 128);
650:         final List<BufferPool> localBufferPools = new ArrayList<>(numLocalBufferPool);
651: 
652:         try {
653:             // create local buffer pools
654:             for (int i = 0; i < numLocalBufferPool; ++i) {
655:                 final BufferPool localPool =
656:                         globalPool.createBufferPool(
657:                                 localPoolRequiredSize, localPoolRequiredSize, localPoolMaxSize);
658:                 localBufferPools.add(localPool);
659:                 assertThat(localPool.getAvailableFuture()).isDone();
660:             }
661: 
662:             // request some segments from the global pool in two different ways
663:             final List<MemorySegment> segments = new ArrayList<>(numberOfSegmentsToRequest - 1);
664:             for (int i = 0; i < numberOfSegmentsToRequest - 1; ++i) {
665:                 segments.add(globalPool.requestPooledMemorySegment());
666:             }
667:             final List<MemorySegment> exclusiveSegments =
668:                     globalPool.requestUnpooledMemorySegments(
669:                             globalPool.getNumberOfAvailableMemorySegments() - 1);
670:             assertThat(globalPool.getAvailableFuture()).isDone();
671:             for (final BufferPool localPool : localBufferPools) {
672:                 assertThat(localPool.getAvailableFuture()).isDone();
673:             }
674: 
675:             // blocking request buffers form local buffer pools
676:             final CountDownLatch latch = new CountDownLatch(numLocalBufferPool);
677:             final BlockingQueue<BufferBuilder> segmentsRequested =
678:                     new ArrayBlockingQueue<>(numBuffers);
679:             final AtomicReference<Throwable> cause = new AtomicReference<>();
680:             for (final BufferPool localPool : localBufferPools) {
681:                 executorService.submit(
682:                         () -> {
683:                             try {
684:                                 for (int num = localPoolMaxSize; num > 0; --num) {
685:                                     segmentsRequested.add(localPool.requestBufferBuilderBlocking());
686:                                 }
687:                             } catch (Exception e) {
688:                                 cause.set(e);
689:                             } finally {
690:                                 latch.countDown();
691:                             }
692:                         });
693:             }
694: 
695:             // wait until all available buffers are requested
696:             while (segmentsRequested.size() + segments.size() + exclusiveSegments.size()
697:                     < numBuffers) {
698:                 Thread.sleep(10);
699:                 assertThat(cause.get()).isNull();
700:             }
701: 
702:             final CompletableFuture<?> globalPoolAvailableFuture = globalPool.getAvailableFuture();
703:             assertThat(globalPoolAvailableFuture).isNotDone();
704: 
705:             final List<CompletableFuture<?>> localPoolAvailableFutures =
706:                     new ArrayList<>(numLocalBufferPool);
707:             for (BufferPool localPool : localBufferPools) {
708:                 CompletableFuture<?> localPoolAvailableFuture = localPool.getAvailableFuture();
709:                 localPoolAvailableFutures.add(localPoolAvailableFuture);
710:                 assertThat(localPoolAvailableFuture).isNotDone();
711:             }
712: 
713:             // recycle the previously requested segments
714:             for (MemorySegment segment : segments) {
715:                 globalPool.recyclePooledMemorySegment(segment);
716:             }
717:             globalPool.recycleUnpooledMemorySegments(exclusiveSegments);
718: 
719:             assertThat(globalPoolAvailableFuture).isDone();
720:             for (CompletableFuture<?> localPoolAvailableFuture : localPoolAvailableFutures) {
721:                 assertThat(localPoolAvailableFuture).isDone();
722:             }
723: 
724:             // wait until all blocking buffer requests finish
725:             latch.await();
726: 
727:             assertThat(cause.get()).isNull();
728:             assertThat(globalPool.getNumberOfAvailableMemorySegments()).isZero();
729:             assertThat(globalPool.getAvailableFuture()).isNotDone();
730:             for (BufferPool localPool : localBufferPools) {
731:                 assertThat(localPool.getAvailableFuture()).isNotDone();
732:                 assertThat(localPool.bestEffortGetNumOfUsedBuffers()).isEqualTo(localPoolMaxSize);
733:             }
734: 
735:             // recycle all the requested buffers
736:             for (BufferBuilder bufferBuilder : segmentsRequested) {
737:                 bufferBuilder.close();
738:             }
739: 
740:         } finally {
741:             for (BufferPool bufferPool : localBufferPools) {
742:                 bufferPool.lazyDestroy();
743:             }
744:             executorService.shutdown();
745:             globalPool.destroy();
746:         }
747:     }
