103:     /**
104:      * Tests creating two buffer pools which together require as many buffers as available but where
105:      * there are less buffers available to the {@link NetworkBufferPool} at the time of the second
106:      * {@link LocalBufferPool} creation.
107:      */
108:     @Test
109:     void testOverprovisioned() throws IOException {
110:         // note: this is also the minimum number of buffers reserved for pool2
111:         int buffersToTakeFromPool1 = numBuffers / 2 + 1;
112:         // note: this is also the minimum number of buffers reserved for pool1
113:         int buffersToTakeFromPool2 = numBuffers - buffersToTakeFromPool1;
114: 
115:         List<Buffer> buffers = new ArrayList<>(numBuffers);
116:         BufferPool bufferPool1 = null, bufferPool2 = null;
117:         try {
118:             bufferPool1 =
119:                     networkBufferPool.createBufferPool(
120:                             buffersToTakeFromPool2, buffersToTakeFromPool2, numBuffers);
121: 
122:             // take more buffers than the minimum required
123:             for (int i = 0; i < buffersToTakeFromPool1; ++i) {
124:                 Buffer buffer = bufferPool1.requestBuffer();
125:                 assertThat(buffer).isNotNull();
126:                 buffers.add(buffer);
127:             }
128:             assertThat(bufferPool1.bestEffortGetNumOfUsedBuffers())
129:                     .isEqualTo(buffersToTakeFromPool1);
130:             assertThat(bufferPool1.getNumBuffers()).isEqualTo(numBuffers);
131: 
132:             // create a second pool which requires more buffers than are available at the moment
133:             bufferPool2 =
134:                     networkBufferPool.createBufferPool(
135:                             buffersToTakeFromPool1, buffersToTakeFromPool1, numBuffers);
136: 
137:             assertThat(bufferPool2.getNumBuffers())
138:                     .isEqualTo(bufferPool2.getExpectedNumberOfMemorySegments());
139:             assertThat(bufferPool1.getNumBuffers())
140:                     .isEqualTo(bufferPool1.getExpectedNumberOfMemorySegments());
141:             assertThat(bufferPool1.requestBuffer()).isNull();
142: 
143:             // take all remaining buffers
144:             for (int i = 0; i < buffersToTakeFromPool2; ++i) {
145:                 Buffer buffer = bufferPool2.requestBuffer();
146:                 assertThat(buffer).isNotNull();
147:                 buffers.add(buffer);
148:             }
149:             assertThat(bufferPool2.bestEffortGetNumOfUsedBuffers())
150:                     .isEqualTo(buffersToTakeFromPool2);
151: 
152:             // we should be able to get one more but this is currently given out to bufferPool1 and
153:             // taken by buffer1
154:             assertThat(bufferPool2.requestBuffer()).isNull();
155: 
156:             // as soon as one excess buffer of bufferPool1 is recycled, it should be available for
157:             // bufferPool2
158:             buffers.remove(0).recycleBuffer();
159:             // recycle returns the excess buffer to the network buffer pool from where it's eagerly
160:             // fetched by pool 2
161:             assertThat(networkBufferPool.getNumberOfAvailableMemorySegments()).isZero();
162:             // verify the number of buffers taken from the pools
163:             assertThat(
164:                             bufferPool1.bestEffortGetNumOfUsedBuffers()
165:                                     + bufferPool1.getNumberOfAvailableMemorySegments())
166:                     .isEqualTo(buffersToTakeFromPool1 - 1);
167:             assertThat(
168:                             bufferPool2.bestEffortGetNumOfUsedBuffers()
169:                                     + bufferPool2.getNumberOfAvailableMemorySegments())
170:                     .isEqualTo(buffersToTakeFromPool2 + 1);
171:         } finally {
172:             for (Buffer buffer : buffers) {
173:                 buffer.recycleBuffer();
174:             }
175:             if (bufferPool1 != null) {
176:                 bufferPool1.lazyDestroy();
177:             }
178:             if (bufferPool2 != null) {
179:                 bufferPool2.lazyDestroy();
180:             }
181:         }
182:     }
