318:     private void testPartitionBufferPool(ResultPartitionType type) throws Exception {
319:         // setup
320:         final int networkBuffersPerChannel = 2;
321:         final int requiredFloatingBuffers = 8;
322:         final NetworkBufferPool globalPool = new NetworkBufferPool(20, 1);
323:         final ResultPartition partition =
324:                 new ResultPartitionBuilder()
325:                         .setResultPartitionType(type)
326:                         .setFileChannelManager(fileChannelManager)
327:                         .setNetworkBuffersPerChannel(networkBuffersPerChannel)
328:                         .setFloatingNetworkBuffersPerGate(requiredFloatingBuffers)
329:                         .setNetworkBufferPool(globalPool)
330:                         .build();
331: 
332:         try {
333:             partition.setup();
334:             BufferPool bufferPool = partition.getBufferPool();
335:             // verify the amount of buffers in created local pool
336:             assertThat(bufferPool.getExpectedNumberOfMemorySegments())
337:                     .isEqualTo(partition.getNumberOfSubpartitions() + 1);
338:             if (type.isBounded()) {
339:                 final int maxNumBuffers =
340:                         networkBuffersPerChannel * partition.getNumberOfSubpartitions()
341:                                 + requiredFloatingBuffers;
342:                 assertThat(bufferPool.getMaxNumberOfMemorySegments()).isEqualTo(maxNumBuffers);
343:             } else {
344:                 assertThat(bufferPool.getMaxNumberOfMemorySegments()).isEqualTo(Integer.MAX_VALUE);
345:             }
346: 
347:         } finally {
348:             // cleanup
349:             globalPool.destroyAllBufferPools();
350:             globalPool.destroy();
351:         }
352:     }
