241:     private void createInputChannelsAndTieredStorageService(
242:             String owningTaskName,
243:             InputGateDeploymentDescriptor inputGateDeploymentDescriptor,
244:             SingleInputGate inputGate,
245:             ResultSubpartitionIndexSet subpartitionIndexSet,
246:             GateBuffersSpec gateBuffersSpec,
247:             InputChannelMetrics metrics,
248:             boolean isSharedInputChannelSupported) {
249:         ShuffleDescriptor[] shuffleDescriptors =
250:                 inputGateDeploymentDescriptor.getShuffleDescriptors();
251: 
252:         // Create the input channels. There is one input channel for each consumed subpartition.
253:         InputChannel[] inputChannels =
254:                 new InputChannel
255:                         [calculateNumChannels(
256:                                 shuffleDescriptors.length,
257:                                 subpartitionIndexSet.size(),
258:                                 isSharedInputChannelSupported)];
259: 
260:         ChannelStatistics channelStatistics = new ChannelStatistics();
261: 
262:         int channelIdx = 0;
263:         final List<TieredStorageConsumerSpec> tieredStorageConsumerSpecs = new ArrayList<>();
264:         List<List<TierShuffleDescriptor>> tierShuffleDescriptors = new ArrayList<>();
265:         for (ShuffleDescriptor descriptor : shuffleDescriptors) {
266:             TieredStoragePartitionId partitionId =
267:                     TieredStorageIdMappingUtils.convertId(descriptor.getResultPartitionID());
268:             if (isSharedInputChannelSupported) {
269:                 inputChannels[channelIdx] =
270:                         createInputChannel(
271:                                 inputGate,
272:                                 channelIdx,
273:                                 gateBuffersSpec.getEffectiveExclusiveBuffersPerChannel(),
274:                                 descriptor,
275:                                 subpartitionIndexSet,
276:                                 channelStatistics,
277:                                 metrics);
278:                 if (tieredStorageConfiguration != null) {
279:                     addTierShuffleDescriptors(tierShuffleDescriptors, descriptor);
280: 
281:                     tieredStorageConsumerSpecs.add(
282:                             new TieredStorageConsumerSpec(
283:                                     inputGate.getInputGateIndex(),
284:                                     partitionId,
285:                                     new TieredStorageInputChannelId(channelIdx),
286:                                     subpartitionIndexSet));
287:                 }
288:                 channelIdx++;
289:             } else {
290:                 for (int subpartitionIndex : subpartitionIndexSet.values()) {
291:                     inputChannels[channelIdx] =
292:                             createInputChannel(
293:                                     inputGate,
294:                                     channelIdx,
295:                                     gateBuffersSpec.getEffectiveExclusiveBuffersPerChannel(),
296:                                     descriptor,
297:                                     new ResultSubpartitionIndexSet(subpartitionIndex),
298:                                     channelStatistics,
299:                                     metrics);
300:                     if (tieredStorageConfiguration != null) {
301:                         addTierShuffleDescriptors(tierShuffleDescriptors, descriptor);
302: 
303:                         tieredStorageConsumerSpecs.add(
304:                                 new TieredStorageConsumerSpec(
305:                                         inputGate.getInputGateIndex(),
306:                                         partitionId,
307:                                         new TieredStorageInputChannelId(channelIdx),
308:                                         new ResultSubpartitionIndexSet(subpartitionIndex)));
309:                     }
310:                     channelIdx++;
311:                 }
312:             }
313:         }
314: 
315:         inputGate.setInputChannels(inputChannels);
316: 
317:         if (tieredStorageConfiguration != null) {
318:             TieredStorageConsumerClient tieredStorageConsumerClient =
319:                     new TieredStorageConsumerClient(
320:                             tieredStorageConfiguration.getTierFactories(),
321:                             tieredStorageConsumerSpecs,
322:                             tierShuffleDescriptors,
323:                             tieredStorageNettyService);
324:             inputGate.setTieredStorageService(
325:                     tieredStorageConsumerSpecs,
326:                     tieredStorageConsumerClient,
327:                     tieredStorageNettyService);
328:         }
329: 
330:         LOG.debug(
331:                 "{}: Created {} input channels ({}).",
332:                 owningTaskName,
333:                 inputChannels.length,
334:                 channelStatistics);
335:     }
