121:             RexCall invocation,
122:             List<ChangelogMode> inputChangelogModes) {
123:         this(
124:                 ExecNodeContext.newNodeId(),
125:                 ExecNodeContext.newContext(StreamExecProcessTableFunction.class),
126:                 ExecNodeContext.newPersistedConfig(
127:                         StreamExecProcessTableFunction.class, tableConfig),
128:                 inputProperties,
129:                 outputType,
130:                 description,
131:                 uid,
132:                 invocation,
133:                 inputChangelogModes);
134:     }
135: 
136:     @JsonCreator
137:     public StreamExecProcessTableFunction(
138:             @JsonProperty(FIELD_NAME_ID) int id,
139:             @JsonProperty(FIELD_NAME_TYPE) ExecNodeContext context,
140:             @JsonProperty(FIELD_NAME_CONFIGURATION) ReadableConfig persistedConfig,
141:             @JsonProperty(FIELD_NAME_INPUT_PROPERTIES) List<InputProperty> inputProperties,
142:             @JsonProperty(FIELD_NAME_OUTPUT_TYPE) RowType outputType,
143:             @JsonProperty(FIELD_NAME_DESCRIPTION) String description,
144:             @JsonProperty(FIELD_NAME_UID) @Nullable String uid,
145:             @JsonProperty(FIELD_NAME_FUNCTION_CALL) RexNode invocation,
146:             @JsonProperty(FIELD_NAME_INPUT_CHANGELOG_MODES)
147:                     List<ChangelogMode> inputChangelogModes) {
148:         super(id, context, persistedConfig, inputProperties, outputType, description);
149:         this.uid = uid;
150:         this.invocation = (RexCall) invocation;
151:         this.inputChangelogModes = inputChangelogModes;
152:     }
153: 
154:     public @Nullable String getUid() {
155:         return uid;
156:     }
157: 
158:     @Override
159:     @SuppressWarnings("unchecked")
160:     protected Transformation<RowData> translateToPlanInternal(
161:             PlannerBase planner, ExecNodeConfig config) {
162:         final List<Transformation<RowData>> inputTransforms =
163:                 getInputEdges().stream()
164:                         .map(e -> (Transformation<RowData>) e.translateToPlan(planner))
165:                         .collect(Collectors.toList());
166:         if (inputTransforms.size() != 1) {
167:             throw new TableException("Process table function only supports exactly one input.");
168:         }
169:         final Transformation<RowData> inputTransform = inputTransforms.get(0);
170: 
171:         final List<Ord<StaticArgument>> providedInputArgs =
172:                 StreamPhysicalProcessTableFunction.getProvidedInputArgs(invocation);
173:         final List<RexNode> operands = invocation.getOperands();
174:         final Set<String> onTimeFields = deriveOnTimeFields(operands);
175:         final List<RuntimeTableSemantics> runtimeTableSemantics =
176:                 providedInputArgs.stream()
177:                         .map(
178:                                 providedInputArg -> {
179:                                     final RexTableArgCall tableArgCall =
180:                                             (RexTableArgCall) operands.get(providedInputArg.i);
181:                                     final StaticArgument tabledArg = providedInputArg.e;
182:                                     return createRuntimeTableSemantics(
183:                                             tabledArg, tableArgCall, onTimeFields);
184:                                 })
185:                         .collect(Collectors.toList());
186:         final List<Integer> timeColumns =
187:                 runtimeTableSemantics.stream()
188:                         .map(RuntimeTableSemantics::timeColumn)
189:                         .collect(Collectors.toList());
190: 
191:         final CodeGeneratorContext ctx =
192:                 new CodeGeneratorContext(config, planner.getFlinkContext().getClassLoader());
193: 
194:         final GeneratedRunnerResult generated =
195:                 ProcessTableRunnerGenerator.generate(
196:                         ctx, invocation, timeColumns, inputChangelogModes);
197:         final GeneratedProcessTableRunner generatedRunner = generated.runner();
198:         final LinkedHashMap<String, StateInfo> stateInfos = generated.stateInfos();
199: 
200:         final List<RuntimeStateInfo> runtimeStateInfos =
201:                 stateInfos.entrySet().stream()
202:                         .map(
203:                                 stateInfo ->
204:                                         createRuntimeStateInfo(
205:                                                 stateInfo.getKey(), stateInfo.getValue(), config))
206:                         .collect(Collectors.toList());
207:         final GeneratedHashFunction[] stateHashCode =
208:                 runtimeStateInfos.stream()
209:                         .map(RuntimeStateInfo::getDataType)
210:                         .map(DataType::getLogicalType)
211:                         .map(
212:                                 t ->
213:                                         HashCodeGenerator.generateRowHash(
214:                                                 ctx,
215:                                                 t,
216:                                                 "StateHashCode",
217:                                                 IntStream.range(0, getFieldCount(t)).toArray()))
218:                         .toArray(GeneratedHashFunction[]::new);
219:         final GeneratedRecordEqualiser[] stateEquals =
220:                 runtimeStateInfos.stream()
221:                         .map(RuntimeStateInfo::getDataType)
222:                         .map(DataType::getLogicalType)
223:                         .map(t -> EqualiserCodeGenerator.generateRowEquals(ctx, t, "StateEquals"))
224:                         .toArray(GeneratedRecordEqualiser[]::new);
225: 
226:         final RuntimeTableSemantics singleTableSemantics;
227:         if (runtimeTableSemantics.isEmpty()) {
228:             // For constant function calls
229:             singleTableSemantics = null;
230:         } else {
231:             singleTableSemantics = runtimeTableSemantics.get(0);
232:         }
233: 
234:         final ProcessTableOperatorFactory operatorFactory =
235:                 new ProcessTableOperatorFactory(
236:                         singleTableSemantics,
237:                         runtimeStateInfos,
238:                         generatedRunner,
239:                         stateHashCode,
240:                         stateEquals);
241: 
242:         final String effectiveUid =
243:                 uid != null ? uid : createTransformationUid(PROCESS_TRANSFORMATION, config);
244: 
245:         final TransformationMetadata metadata =
246:                 new TransformationMetadata(
247:                         effectiveUid,
248:                         createTransformationName(config),
249:                         createTransformationDescription(config));
250: 
251:         final OneInputTransformation<RowData, RowData> transform =
252:                 ExecNodeUtil.createOneInputTransformation(
253:                         inputTransform,
254:                         metadata,
255:                         operatorFactory,
256:                         InternalTypeInfo.of(getOutputType()),
257:                         inputTransform.getParallelism(),
258:                         false);
259: 
260:         // For one input (but non-constant) functions with set semantics
261:         if (singleTableSemantics != null && singleTableSemantics.hasSetSemantics()) {
262:             final RowDataKeySelector selector =
263:                     KeySelectorUtil.getRowDataSelector(
264:                             planner.getFlinkContext().getClassLoader(),
265:                             singleTableSemantics.partitionByColumns(),
266:                             (InternalTypeInfo<RowData>) inputTransform.getOutputType());
267:             transform.setStateKeySelector(selector);
268:             transform.setStateKeyType(selector.getProducedType());
269:         }
270: 
271:         if (inputsContainSingleton()) {
272:             transform.setParallelism(1);
273:             transform.setMaxParallelism(1);
274:         }
275: 
276:         return transform;
277:     }
278: 
279:     private RuntimeTableSemantics createRuntimeTableSemantics(
280:             StaticArgument tableArg, RexTableArgCall tableArgCall, Set<String> onTimeFields) {
281:         final RowKind[] kinds =
282:                 inputChangelogModes
283:                         .get(tableArgCall.getInputIndex())
284:                         .getContainedKinds()
285:                         .toArray(RowKind[]::new);
286:         final byte[] consumedChangelogMode = new byte[kinds.length];
287:         IntStream.range(0, kinds.length).forEach(i -> consumedChangelogMode[i] = kinds[i].toByteValue());
288:         final DataType dataType;
289:         if (tableArg.getDataType().isPresent()) {
290:             dataType = tableArg.getDataType().get();
291:         } else {
292:             dataType = DataTypes.of(FlinkTypeFactory.toLogicalRowType(tableArgCall.type));
293:         }
294: 
295:         final int timeColumn =
296:                 onTimeFields.stream()
297:                         .map(
298:                                 onTimeField ->
299:                                         tableArgCall.getType().getField(onTimeField, true, false))
300:                         .filter(Objects::nonNull)
301:                         .map(RelDataTypeField::getIndex)
302:                         .findFirst()
303:                         .orElse(-1);
304: 
305:         return new RuntimeTableSemantics(
306:                 tableArg.getName(),
307:                 tableArgCall.getInputIndex(),
308:                 dataType,
309:                 tableArgCall.getPartitionKeys(),
310:                 consumedChangelogMode,
311:                 tableArg.is(StaticArgumentTrait.PASS_COLUMNS_THROUGH),
312:                 tableArg.is(StaticArgumentTrait.TABLE_AS_SET),
313:                 timeColumn);
314:     }
315: 
316:     private static RuntimeStateInfo createRuntimeStateInfo(
317:             String name, StateInfo stateInfo, ExecNodeConfig config) {
318:         return new RuntimeStateInfo(
319:                 name,
320:                 stateInfo.getDataType(),
321:                 deriveStateTimeToLive(
322:                         stateInfo.getTimeToLive().orElse(null), config.getStateRetentionTime()));
323:     }
324: 
325:     private static long deriveStateTimeToLive(
326:             @Nullable Duration declaration, long globalRetentionTime) {
327:         // User declaration take precedence. Including a potential 0.
328:         if (declaration != null) {
329:             return declaration.toMillis();
330:         }
331:         // This prepares the state layout of every PTF. It makes enabling state TTL at a later
332:         // point in time possible. The past has shown that users often don't consider ever-growing
333:         // state initially and would like to enable it later - without breaking the savepoint.
334:         // Setting it to Long.MAX_VALUE is a better default than 0. It comes with overhead which is
335:         // why a 0 declaration can override this for efficiency.
336:         if (globalRetentionTime == 0) {
337:             return Long.MAX_VALUE;
338:         }
339:         return globalRetentionTime;
340:     }
341: }
