419:     private Optional<REPORTER> loadReporter(
420:             final String reporterName,
421:             final Configuration reporterConfig,
422:             final Map<String, REPORTER_FACTORY> reporterFactories) {
423: 
424:         final String factoryClassName = reporterConfig.get(reporterSetupInfo.factoryClassConfig);
425: 
426:         if (factoryClassName != null) {
427:             return loadViaFactory(
428:                     factoryClassName, reporterName, reporterConfig, reporterFactories);
429:         }
430: 
431:         LOG.warn(
432:                 "No reporter factory set for reporter {}. Events might not be exposed/reported.",
433:                 reporterName);
434:         return Optional.empty();
435:     }
436: 
437:     private Optional<REPORTER> loadViaFactory(
438:             final String factoryClassName,
439:             final String reporterName,
440:             final Configuration reporterConfig,
441:             final Map<String, REPORTER_FACTORY> reporterFactories) {
442: 
443:         REPORTER_FACTORY factory = reporterFactories.get(factoryClassName);
444: 
445:         if (factory == null) {
446:             LOG.warn(
447:                     "The reporter factory ({}) could not be found for reporter {}. Available factories: {}.",
448:                     factoryClassName,
449:                     reporterName,
450:                     reporterFactories.keySet());
451:             return Optional.empty();
452:         } else {
453:             return loadViaFactory(reporterConfig, factory);
454:         }
455:     }
456: 
457:     private Optional<REPORTER> loadViaFactory(
458:             final Configuration reporterConfig, final REPORTER_FACTORY factory) {
459: 
460:         final MetricConfig metricConfig = new MetricConfig();
461:         reporterConfig.addAllToProperties(metricConfig);
462: 
463:         return Optional.of(reporterSetupInfo.reporterFactoryAdapter.invoke(factory, metricConfig));
464:     }
