147: 
148:     protected void serializeMetadata(CheckpointMetadata checkpointMetadata, DataOutputStream dos)
149:             throws IOException {
150:         // first: checkpoint ID
151:         dos.writeLong(checkpointMetadata.getCheckpointId());
152: 
153:         // second: master state
154:         final Collection<MasterState> masterStates = checkpointMetadata.getMasterStates();
155:         dos.writeInt(masterStates.size());
156:         for (MasterState ms : masterStates) {
157:             serializeMasterState(ms, dos);
158:         }
159: 
160:         // third: operator states
161:         Collection<OperatorState> operatorStates = checkpointMetadata.getOperatorStates();
162:         dos.writeInt(operatorStates.size());
163: 
164:         for (OperatorState operatorState : operatorStates) {
165:             serializeOperatorState(operatorState, dos);
166:         }
167:     }
168: 
169:     protected CheckpointMetadata deserializeMetadata(
170:             DataInputStream dis, @Nullable String externalPointer) throws IOException {
171: 
172:         final DeserializationContext context =
173:                 externalPointer == null ? null : new DeserializationContext(externalPointer);
174: 
175:         // first: checkpoint ID
176:         final long checkpointId = dis.readLong();
177:         if (checkpointId < 0) {
178:             throw new IOException("invalid checkpoint ID: " + checkpointId);
179:         }
180: 
181:         // second: master state
182:         final List<MasterState> masterStates;
183:         final int numMasterStates = dis.readInt();
184: 
185:         if (numMasterStates == 0) {
186:             masterStates = Collections.emptyList();
187:         } else if (numMasterStates > 0) {
188:             masterStates = new ArrayList<>(numMasterStates);
189:             for (int i = 0; i < numMasterStates; i++) {
190:                 masterStates.add(deserializeMasterState(dis));
191:             }
192:         } else {
193:             throw new IOException("invalid number of master states: " + numMasterStates);
194:         }
195: 
196:         // third: operator states
197:         final int numTaskStates = dis.readInt();
198:         final List<OperatorState> operatorStates = new ArrayList<>(numTaskStates);
199: 
200:         for (int i = 0; i < numTaskStates; i++) {
201:             operatorStates.add(deserializeOperatorState(dis, context));
202:         }
203: 
204:         return new CheckpointMetadata(checkpointId, operatorStates, masterStates);
205:     }
