207:     // ------------------------------------------------------------------------
208:     //  master state (de)serialization methods
209:     // ------------------------------------------------------------------------
210: 
211:     protected void serializeMasterState(MasterState state, DataOutputStream dos)
212:             throws IOException {
213:         // magic number for error detection
214:         dos.writeInt(MASTER_STATE_MAGIC_NUMBER);
215: 
216:         // for safety, we serialize first into an array and then write the array and its
217:         // length into the checkpoint
218:         final ByteArrayOutputStream baos = new ByteArrayOutputStream();
219:         final DataOutputStream out = new DataOutputStream(baos);
220: 
221:         out.writeInt(state.version());
222:         out.writeUTF(state.name());
223: 
224:         final byte[] bytes = state.bytes();
225:         out.writeInt(bytes.length);
226:         out.write(bytes, 0, bytes.length);
227: 
228:         out.close();
229:         byte[] data = baos.toByteArray();
230: 
231:         dos.writeInt(data.length);
232:         dos.write(data, 0, data.length);
233:     }
234: 
235:     protected MasterState deserializeMasterState(DataInputStream dis) throws IOException {
236:         final int magicNumber = dis.readInt();
237:         if (magicNumber != MASTER_STATE_MAGIC_NUMBER) {
238:             throw new IOException("incorrect magic number in master styte byte sequence");
239:         }
240: 
241:         final int numBytes = dis.readInt();
242:         if (numBytes <= 0) {
243:             throw new IOException("found zero or negative length for master state bytes");
244:         }
245: 
246:         final byte[] data = new byte[numBytes];
247:         dis.readFully(data);
248: 
249:         final DataInputStream in = new DataInputStream(new ByteArrayInputStream(data));
250: 
251:         final int version = in.readInt();
252:         final String name = in.readUTF();
253: 
254:         final byte[] bytes = new byte[in.readInt()];
255:         in.readFully(bytes);
256: 
257:         // check that the data is not corrupt
258:         if (in.read() != -1) {
259:             throw new IOException("found trailing bytes in master state");
260:         }
261: 
262:         return new MasterState(name, bytes, version);
263:     }
