720:     static void serializeStreamStateHandle(StreamStateHandle stateHandle, DataOutputStream dos)
721:             throws IOException {
722:         if (stateHandle == null) {
723:             dos.writeByte(NULL_HANDLE);
724: 
725:         } else if (stateHandle instanceof RelativeFileStateHandle) {
726:             dos.writeByte(RELATIVE_STREAM_STATE_HANDLE);
727:             RelativeFileStateHandle relativeFileStateHandle = (RelativeFileStateHandle) stateHandle;
728:             dos.writeUTF(relativeFileStateHandle.getRelativePath());
729:             dos.writeLong(relativeFileStateHandle.getStateSize());
730:         } else if (stateHandle instanceof SegmentFileStateHandle) {
731:             if (stateHandle instanceof EmptySegmentFileStateHandle) {
732:                 dos.writeByte(EMPTY_SEGMENT_FILE_HANDLE);
