826:     @Nullable
827:     static ByteStreamStateHandle deserializeAndCheckByteStreamStateHandle(
828:             DataInputStream dis, @Nullable DeserializationContext context) throws IOException {
829: 
830:         final StreamStateHandle handle = deserializeStreamStateHandle(dis, context);
831:         if (handle == null || handle instanceof ByteStreamStateHandle) {
832:             return (ByteStreamStateHandle) handle;
833:         } else {
834:             throw new IOException(
835:                     "Expected a ByteStreamStateHandle but found a " + handle.getClass().getName());
836:         }
837:     }
