843:     @Nullable
844:     private static <T> T extractSingleton(Collection<T> collection) {
845:         if (collection == null || collection.isEmpty()) {
846:             return null;
847:         }
848: 
849:         if (collection.size() == 1) {
850:             return collection.iterator().next();
851:         } else {
852:             throw new IllegalStateException(
853:                     "Expected singleton collection, but found size: " + collection.size());
854:         }
855:     }
