626:     @ParameterizedTest
627:     @ValueSource(booleans = {true, false})
628:     public void testInternalParallelismChangeBehavior(boolean parallelismChanged) throws Exception {
629:         try (MockExecutingContext adaptiveSchedulerCtx = new MockExecutingContext()) {
630:             final AtomicBoolean onChangeCalled = new AtomicBoolean();
631:             final Function<StateTransitionManager.Context, StateTransitionManager>
632:                     stateTransitionManagerFactory =
633:                             transitionCtx ->
634:                                     TestingStateTransitionManager.withOnChangeEventOnly(
635:                                             () -> {
636:                                                 assertThat(transitionCtx.hasDesiredResources())
637:                                                         .isEqualTo(parallelismChanged);
638:                                                 assertThat(transitionCtx.hasSufficientResources())
639:                                                         .isEqualTo(parallelismChanged);
640:                                                 onChangeCalled.set(true);
641:                                             });
642: 
643:             final MockExecutionJobVertex mockExecutionJobVertex =
644:                     new MockExecutionJobVertex(MockExecutionVertex::new);
645: 
646:             final ExecutionGraph executionGraph =
647:                     new MockExecutionGraph(() -> Collections.singletonList(mockExecutionJobVertex));
648: 
649:             adaptiveSchedulerCtx.setHasDesiredResources(() -> true);
650:             adaptiveSchedulerCtx.setHasSufficientResources(() -> true);
651:             adaptiveSchedulerCtx.setVertexParallelism(
652:                     new VertexParallelism(
653:                             executionGraph.getAllVertices().values().stream()
654:                                     .collect(
655:                                             Collectors.toMap(
656:                                                     AccessExecutionJobVertex::getJobVertexId,
657:                                                     v ->
658:                                                             parallelismChanged
659:                                                                     ? 1 + v.getParallelism()
660:                                                                     : v.getParallelism()))));
661: 
662:             final Executing exec =
663:                     new ExecutingStateBuilder()
664:                             .setStateTransitionManagerFactory(stateTransitionManagerFactory)
665:                             .setExecutionGraph(executionGraph)
666:                             .build(adaptiveSchedulerCtx);
667: 
668:             exec.onNewResourcesAvailable();
