211:     private static void closeInExecutorService(
212:             @Nullable AdaptiveScheduler scheduler, Executor executor) {
213:         if (scheduler != null) {
214:             final CompletableFuture<Void> closeFuture = new CompletableFuture<>();
215:             executor.execute(
216:                     () -> {
217:                         try {
218:                             scheduler.cancel();
219: 
220:                             FutureUtils.forward(scheduler.closeAsync(), closeFuture);
221:                         } catch (Throwable t) {
222:                             closeFuture.completeExceptionally(t);
223:                         }
224:                     });
225: 
226:             // we have to wait for the job termination outside the main thread because the
227:             // cancellation tasks are scheduled on the main thread as well.
228:             scheduler
229:                     .getJobTerminationFuture()
230:                     .whenCompleteAsync(
231:                             (jobStatus, error) -> {
232:                                 assertThat(scheduler.getState().getClass())
233:                                         .isEqualTo(Finished.class);
234: 
235:                                 if (error != null) {
236:                                     closeFuture.completeExceptionally(error);
237:                                 } else {
238:                                     try {
239:                                         FutureUtils.forward(scheduler.closeAsync(), closeFuture);
240:                                     } catch (Throwable t) {
241:                                         closeFuture.completeExceptionally(t);
242:                                     }
243:                                 }
244:                             },
245:                             executor);
246:             assertThatFuture(closeFuture).eventuallySucceeds();
247:         }
248:     }
