1141:         final int parallelism = 240;
1142:         final int expectedMaxParallelism =
1143:                 KeyGroupRangeAssignment.computeDefaultMaxParallelism(parallelism);
1144:         final JobVertex vertex = createNoOpVertex(parallelism);
1145:         final JobGraph jobGraph = streamingJobGraph(vertex);
1146: 
1147:         final DefaultDeclarativeSlotPool declarativeSlotPool =
1148:                 createDeclarativeSlotPool(jobGraph.getJobID(), singleThreadMainThreadExecutor);
1149: 
1150:         scheduler =
