1152:                                 jobGraph,
1153:                                 singleThreadMainThreadExecutor,
1154:                                 EXECUTOR_RESOURCE.getExecutor())
1155:                         .setDeclarativeSlotPool(declarativeSlotPool)
1156:                         .setJobMasterConfiguration(createConfigurationWithNoTimeouts())
1157:                         .build();
1158: 
1159:         final SubmissionBufferingTaskManagerGateway taskManagerGateway =
1160:                 new SubmissionBufferingTaskManagerGateway(1 + parallelism);
1161:         taskManagerGateway.setCancelConsumer(createCancelConsumer(scheduler));
1162: 
1163:         // offer just enough resources to run at the lowest possible parallelism
1164:         singleThreadMainThreadExecutor.execute(
1165:                 () -> {
1166:                     scheduler.startScheduling();
1167:                     offerSlots(
1168:                             declarativeSlotPool,
1169:                             createSlotOffersForResourceRequirements(
1170:                                     ResourceCounter.withResource(ResourceProfile.UNKNOWN, 1)),
1171:                             taskManagerGateway);
1172:                 });
1173: 
1174:         // Wait for task to be submitted
1175:         taskManagerGateway.waitForSubmissions(1);
1176: 
1177:         ArchivedExecutionGraph executionGraph =
1178:                 getArchivedExecutionGraphForRunningJob(scheduler).get();
1179:         ArchivedExecutionJobVertex archivedVertex = executionGraph.getJobVertex(vertex.getID());
1180: 
1181:         // ensure that the parallelism was submitted based on what is available
1182:         assertThat(archivedVertex.getParallelism()).isOne();
1183:         // and that the max parallelism was submitted based on what was configured
1184:         assertThat(archivedVertex.getMaxParallelism()).isEqualTo(expectedMaxParallelism);
1185: 
1186:         // offer the resources to run at full parallelism
1187:         singleThreadMainThreadExecutor.execute(
1188:                 () -> {
1189:                     offerSlots(
1190:                             declarativeSlotPool,
1191:                             createSlotOffersForResourceRequirements(
1192:                                     ResourceCounter.withResource(
1193:                                             ResourceProfile.UNKNOWN, parallelism)),
1194:                             taskManagerGateway);
1195:                 });
1196: 
1197:         // wait for the job to be re-submitted
1198:         taskManagerGateway.waitForSubmissions(parallelism);
1199: 
1200:         ArchivedExecutionGraph resubmittedExecutionGraph =
