1202:         ArchivedExecutionJobVertex resubmittedArchivedVertex =
1203:                 resubmittedExecutionGraph.getJobVertex(vertex.getID());
1204: 
1205:         // ensure that the parallelism was submitted based on what is available
1206:         assertThat(resubmittedArchivedVertex.getParallelism()).isEqualTo(parallelism);
1207:         // and that the max parallelism was submitted based on what was configured
1208:         assertThat(resubmittedArchivedVertex.getMaxParallelism()).isEqualTo(expectedMaxParallelism);
