1473:     private SubmissionBufferingTaskManagerGateway createSubmissionBufferingTaskManagerGateway(
1474:             int parallelism, SchedulerNG scheduler) {
1475:         SubmissionBufferingTaskManagerGateway taskManagerGateway =
1476:                 new SubmissionBufferingTaskManagerGateway(parallelism);
1477:         taskManagerGateway.setCancelConsumer(
1478:                 executionAttemptID ->
1479:                         singleThreadMainThreadExecutor.execute(
1480:                                 () ->
1481:                                         scheduler.updateTaskExecutionState(
1482:                                                 new TaskExecutionState(
1483:                                                         executionAttemptID,
1484:                                                         ExecutionState.CANCELED))));
1485:         return taskManagerGateway;
1486:     }
