1488:     private void startJobWithSlotsMatchingParallelism(
1489:             SchedulerNG scheduler,
1490:             DeclarativeSlotPool declarativeSlotPool,
1491:             TaskManagerGateway taskManagerGateway,
1492:             int parallelism) {
1493:         singleThreadMainThreadExecutor.execute(
1494:                 () -> {
1495:                     scheduler.startScheduling();
1496:                     offerSlots(
1497:                             declarativeSlotPool,
1498:                             createSlotOffersForResourceRequirements(
1499:                                     ResourceCounter.withResource(
1500:                                             ResourceProfile.UNKNOWN, parallelism)),
1501:                             taskManagerGateway);
1502:                 });
1503:     }
1504: 
1505:     private void awaitJobReachingParallelism(
1506:             SubmissionBufferingTaskManagerGateway taskManagerGateway,
1507:             SchedulerNG scheduler,
1508:             int parallelism)
1509:             throws Exception {
1510:         // Wait for all tasks to be submitted
1511:         taskManagerGateway.waitForSubmissions(parallelism);
1512: 
1513:         final ArchivedExecutionGraph executionGraph =
1514:                 CompletableFuture.supplyAsync(
1515:                                 () -> scheduler.requestJob().getArchivedExecutionGraph(),
1516:                                 singleThreadMainThreadExecutor)
1517:                         .get();
1518: 
1519:         assertThat(executionGraph.getJobVertex(JOB_VERTEX.getID()).getParallelism())
1520:                 .isEqualTo(parallelism);
1521:     }
