1532:     private static JobResourceRequirements createRequirementsWithLowerAndUpperParallelism(
1533:             int lowerParallelism, int upperParallelism) {
1534:         return new JobResourceRequirements(
1535:                 Collections.singletonMap(
1536:                         JOB_VERTEX.getID(),
1537:                         new JobVertexResourceRequirements(
1538:                                 new JobVertexResourceRequirements.Parallelism(
1539:                                         lowerParallelism, upperParallelism))));
1540:     }
