2132:     @Test
2133:     void testIdleSlotsAreReleasedAfterDownScalingTriggeredByLoweredResourceRequirements()
2134:             throws Exception {
2135:         final JobGraph jobGraph = createJobGraph();
2136:         final Duration slotIdleTimeout = Duration.ofMillis(10);
2137: 
2138:         final Configuration configuration = createConfigurationWithNoTimeouts();
2139:         configuration.set(JobManagerOptions.SLOT_IDLE_TIMEOUT, slotIdleTimeout);
2140: 
2141:         final DeclarativeSlotPool declarativeSlotPool =
2142:                 createDeclarativeSlotPool(
2143:                         jobGraph.getJobID(), singleThreadMainThreadExecutor, slotIdleTimeout);
2144:         scheduler =
2145:                 new AdaptiveSchedulerBuilder(
2146:                                 jobGraph,
2147:                                 singleThreadMainThreadExecutor,
2148:                                 EXECUTOR_RESOURCE.getExecutor())
2149:                         .setDeclarativeSlotPool(declarativeSlotPool)
2150:                         .setJobMasterConfiguration(configuration)
2151:                         .build();
2152: 
2153:         final int numInitialSlots = 4;
2154:         final int numSlotsAfterDownscaling = 2;
2155: 
2156:         final SubmissionBufferingTaskManagerGateway taskManagerGateway =
2157:                 new SubmissionBufferingTaskManagerGateway(numInitialSlots);
2158: 
2159:         taskManagerGateway.setCancelConsumer(createCancelConsumer(scheduler));
2160: 
2161:         singleThreadMainThreadExecutor.execute(
2162:                 () -> {
2163:                     scheduler.startScheduling();
2164:                     offerSlots(
2165:                             declarativeSlotPool,
2166:                             createSlotOffersForResourceRequirements(
2167:                                     ResourceCounter.withResource(
2168:                                             ResourceProfile.UNKNOWN, numInitialSlots)),
2169:                             taskManagerGateway);
2170:                 });
2171: 
2172:         // wait for all tasks to be submitted
2173:         taskManagerGateway.waitForSubmissions(numInitialSlots);
2174: 
2175:         // lower the resource requirements
2176:         singleThreadMainThreadExecutor.execute(
2177:                 () ->
2178:                         scheduler.updateJobResourceRequirements(
2179:                                 JobResourceRequirements.newBuilder()
2180:                                         .setParallelismForJobVertex(
2181:                                                 JOB_VERTEX.getID(), 1, numSlotsAfterDownscaling)
2182:                                         .build()));
2183: 
2184:         // job should be resubmitted with lower parallelism
2185:         taskManagerGateway.waitForSubmissions(numSlotsAfterDownscaling);
2186: 
2187:         // and excessive slots should be freed
2188:         taskManagerGateway.waitForFreedSlots(numInitialSlots - numSlotsAfterDownscaling);
2189: 
2190:         final CompletableFuture<JobStatus> jobStatusFuture = new CompletableFuture<>();
2191:         singleThreadMainThreadExecutor.execute(
2192:                 () -> jobStatusFuture.complete(scheduler.getState().getJobStatus()));
2193:         assertThatFuture(jobStatusFuture).eventuallySucceeds().isEqualTo(JobStatus.RUNNING);
2194: 
2195:         // make sure we haven't freed up any more slots
2196:         assertThat(taskManagerGateway.freedSlots).isEmpty();
2197:     }
