2320:     private void testCheckpointStatsEventBeingExecutedInTheMainThread(
2321:             Consumer<CheckpointStatsListener> eventCallback,
2322:             int eventRepetitions,
2323:             int triggerOnFailedCheckpointCount)
2324:             throws Exception {
2325: 
2326:         final CompletableFuture<CheckpointStatsListener> statsListenerInstantiatedFuture =
2327:                 new CompletableFuture<>();
2328:         final BlockingQueue<Integer> eventQueue = new ArrayBlockingQueue<>(1);
2329: 
2330:         scheduler =
2331:                 createSchedulerThatReachesExecutingState(
2332:                         PARALLELISM,
2333:                         triggerOnFailedCheckpointCount,
2334:                         eventQueue,
2335:                         statsListenerInstantiatedFuture);
2336: 
2337:         // start scheduling to reach Executing state
2338:         singleThreadMainThreadExecutor.execute(scheduler::startScheduling);
2339: 
2340:         final CheckpointStatsListener statsListener = statsListenerInstantiatedFuture.get();
2341:         assertThat(statsListener)
2342:                 .as("The CheckpointStatsListener should have been instantiated.")
2343:                 .isNotNull();
2344: 
2345:         // the first trigger happens in the Executing initialization - let's wait for that event
2346:         // to pass
2347:         assertThat(eventQueue.take())
2348:                 .as(
2349:                         "The first event should have been appeared during Executing state initialization and should be ignored.")
2350:                 .isEqualTo(0);
2351: 
2352:         // counting the failed checkpoints only starts on a change event
2353:         scheduler.updateJobResourceRequirements(
2354:                 JobResourceRequirements.newBuilder()
2355:                         .setParallelismForJobVertex(JOB_VERTEX.getID(), 1, PARALLELISM - 1)
2356:                         .build());
2357: 
2358:         for (int i = 0; i < eventRepetitions; i++) {
2359:             assertThatNoException()
2360:                     .as(
2361:                             "Triggering the event from outside the main thread should not have caused an error.")
2362:                     .isThrownBy(() -> eventCallback.accept(statsListener));
2363:         }
2364: 
2365:         assertThat(eventQueue.take()).as("Only one event should have been observed.").isEqualTo(1);
2366:     }
