2645:     /**
2646:      * A {@link SimpleAckingTaskManagerGateway} that buffers all the task submissions into a
2647:      * blocking queue, allowing one to wait for an arbitrary number of submissions.
2648:      */
2649:     public static class SubmissionBufferingTaskManagerGateway
2650:             extends SimpleAckingTaskManagerGateway {
2651:         final BlockingQueue<TaskDeploymentDescriptor> submittedTasks;
2652:         final BlockingQueue<AllocationID> freedSlots;
2653: 
2654:         public SubmissionBufferingTaskManagerGateway(int capacity) {
2655:             submittedTasks = new ArrayBlockingQueue<>(capacity);
2656:             freedSlots = new ArrayBlockingQueue<>(capacity);
2657:             initializeFunctions();
2658:         }
2659: 
2660:         @Override
2661:         public void setSubmitConsumer(Consumer<TaskDeploymentDescriptor> submitConsumer) {
2662:             super.setSubmitConsumer(
2663:                     taskDeploymentDescriptor -> {
2664:                         Preconditions.checkState(submittedTasks.offer(taskDeploymentDescriptor));
2665:                         submitConsumer.accept(taskDeploymentDescriptor);
2666:                     });
2667:         }
2668: 
2669:         @Override
2670:         public void setFreeSlotFunction(
2671:                 BiFunction<AllocationID, Throwable, CompletableFuture<Acknowledge>>
2672:                         freeSlotFunction) {
2673:             super.setFreeSlotFunction(
2674:                     (allocationID, throwable) -> {
2675:                         Preconditions.checkState(freedSlots.offer(allocationID));
2676:                         return freeSlotFunction.apply(allocationID, throwable);
2677:                     });
2678:         }
2679: 
2680:         /**
2681:          * Block until an arbitrary number of submissions have been received.
2682:          *
2683:          * @param numSubmissions The number of submissions to wait for
2684:          * @return the list of the waited-for submissions
2685:          * @throws InterruptedException if a timeout is exceeded waiting for a submission
2686:          */
2687:         public List<TaskDeploymentDescriptor> waitForSubmissions(int numSubmissions)
2688:                 throws InterruptedException {
2689:             List<TaskDeploymentDescriptor> descriptors = new ArrayList<>();
2690:             for (int i = 0; i < numSubmissions; i++) {
2691:                 descriptors.add(submittedTasks.take());
2692:             }
2693:             return descriptors;
2694:         }
2695: 
2696:         public List<AllocationID> waitForFreedSlots(int numFreedSlots) throws InterruptedException {
2697:             final List<AllocationID> allocationIds = new ArrayList<>();
2698:             for (int i = 0; i < numFreedSlots; i++) {
2699:                 allocationIds.add(freedSlots.take());
2700:             }
2701:             return allocationIds;
2702:         }
2703: 
2704:         private void initializeFunctions() {
2705:             setSubmitConsumer(ignored -> {});
2706:             setFreeSlotFunction(
2707:                     (allocationId, throwable) ->
2708:                             CompletableFuture.completedFuture(Acknowledge.get()));
2709:         }
2710:     }
