450:     public List<JobVertex> getVerticesSortedTopologicallyFromSources()
451:             throws InvalidProgramException {
452:         // early out on empty lists
453:         if (this.taskVertices.isEmpty()) {
454:             return Collections.emptyList();
455:         }
456: 
457:         List<JobVertex> sorted = new ArrayList<JobVertex>(this.taskVertices.size());
458:         Set<JobVertex> remaining = new LinkedHashSet<JobVertex>(this.taskVertices.values());
459: 
460:         // start by finding the vertices with no input edges
461:         // and the ones with disconnected inputs (that refer to some standalone data set)
462:         {
463:             Iterator<JobVertex> iter = remaining.iterator();
464:             while (iter.hasNext()) {
465:                 JobVertex vertex = iter.next();
466: 
467:                 if (vertex.hasNoConnectedInputs()) {
468:                     sorted.add(vertex);
469:                     iter.remove();
470:                 }
471:             }
472:         }
473: 
474:         int startNodePos = 0;
475: 
476:         // traverse from the nodes that were added until we found all elements
477:         while (!remaining.isEmpty()) {
478: 
479:             // first check if we have more candidates to start traversing from. if not, then the
480:             // graph is cyclic, which is not permitted
481:             if (startNodePos >= sorted.size()) {
482:                 throw new InvalidProgramException("The job graph is cyclic.");
483:             }
484: 
485:             JobVertex current = sorted.get(startNodePos++);
486:             addNodesThatHaveNoNewPredecessors(current, sorted, remaining);
487:         }
488: 
489:         return sorted;
490:     }
491: 
492:     private void addNodesThatHaveNoNewPredecessors(
493:             JobVertex start, List<JobVertex> target, Set<JobVertex> remaining) {
494: 
495:         // forward traverse over all produced data sets and all their consumers
496:         for (IntermediateDataSet dataSet : start.getProducedDataSets()) {
497:             for (JobEdge edge : dataSet.getConsumers()) {
498: 
499:                 // a vertex can be added, if it has no predecessors that are still in the
500:                 // 'remaining' set
501:                 JobVertex v = edge.getTarget();
502:                 if (!remaining.contains(v)) {
503:                     continue;
504:                 }
505: 
506:                 boolean hasNewPredecessors = false;
507: 
508:                 for (JobEdge e : v.getInputs()) {
509:                     // skip the edge through which we came
510:                     if (e == edge) {
511:                         continue;
512:                     }
513: 
514:                     IntermediateDataSet source = e.getSource();
515:                     if (remaining.contains(source.getProducer())) {
516:                         hasNewPredecessors = true;
517:                         break;
518:                     }
519:                 }
520: 
521:                 if (!hasNewPredecessors) {
522:                     target.add(v);
523:                     remaining.remove(v);
524:                     addNodesThatHaveNoNewPredecessors(v, target, remaining);
525:                 }
526:             }
527:         }
528:     }
