50:     /**
51:      * Creates the {@link ExecutionPlan} corresponding to the provided {@link Pipeline}.
52:      *
53:      * @param pipeline the pipeline whose job graph we are computing.
54:      * @param configuration the configuration with the necessary information such as jars and
55:      *     classpaths to be included, the parallelism of the job and potential savepoint settings
56:      *     used to bootstrap its state.
57:      * @param userClassloader the classloader which can load user classes.
58:      * @return the corresponding {@link ExecutionPlan}.
59:      */
60:     public static ExecutionPlan getExecutionPlan(
61:             @Nonnull final Pipeline pipeline,
62:             @Nonnull final Configuration configuration,
63:             @Nonnull ClassLoader userClassloader)
64:             throws MalformedURLException {
65:         checkNotNull(pipeline);
66:         checkNotNull(configuration);
67: 
68:         final ExecutionConfigAccessor executionConfigAccessor =
69:                 ExecutionConfigAccessor.fromConfiguration(configuration);
70:         final ExecutionPlan executionPlan =
71:                 FlinkPipelineTranslationUtil.getJobGraph(
72:                         userClassloader,
73:                         pipeline,
74:                         configuration,
75:                         executionConfigAccessor.getParallelism());
76: 
77:         configuration
78:                 .getOptional(PipelineOptionsInternal.PIPELINE_FIXED_JOB_ID)
79:                 .ifPresent(strJobID -> executionPlan.setJobID(JobID.fromHexString(strJobID)));
80: 
81:         if (configuration.get(DeploymentOptions.ATTACHED)
82:                 && configuration.get(DeploymentOptions.SHUTDOWN_IF_ATTACHED)) {
83:             executionPlan.setInitialClientHeartbeatTimeout(
84:                     configuration.get(ClientOptions.CLIENT_HEARTBEAT_TIMEOUT).toMillis());
85:         }
86: 
87:         executionPlan.addJars(executionConfigAccessor.getJars());
88:         executionPlan.setClasspaths(executionConfigAccessor.getClasspaths());
89:         executionPlan.setSavepointRestoreSettings(executionConfigAccessor.getSavepointRestoreSettings());
90: 
91:         return executionPlan;
