653:     private ExecutionPlan retrieveJobGraph(
654:             PackagedProgramRetriever retrieverUnderTest, Configuration configuration)
655:             throws FlinkException, ProgramInvocationException, MalformedURLException {
656:         final PackagedProgram packagedProgram = retrieverUnderTest.getPackagedProgram();
657: 
658:         final int defaultParallelism = configuration.get(CoreOptions.DEFAULT_PARALLELISM);
659:         ConfigUtils.encodeCollectionToConfig(
660:                 configuration,
661:                 PipelineOptions.JARS,
662:                 packagedProgram.getJobJarAndDependencies(),
663:                 URL::toString);
664:         ConfigUtils.encodeCollectionToConfig(
665:                 configuration,
666:                 PipelineOptions.CLASSPATHS,
667:                 packagedProgram.getClasspaths(),
668:                 URL::toString);
669: 
670:         final Pipeline pipeline =
671:                 PackagedProgramUtils.getPipelineFromProgram(
672:                         packagedProgram, configuration, defaultParallelism, false);
673:         return PipelineExecutorUtils.getExecutionPlan(
674:                 pipeline, configuration, packagedProgram.getUserCodeClassLoader());
675:     }
676: 
677:     private static List<String> extractRelativizedURLsForJarsFromDirectory(File directory)
678:             throws MalformedURLException {
679:         Preconditions.checkArgument(
680:                 directory.listFiles() != null,
681:                 "The passed File does not seem to be a directory or is not accessible: "
682:                         + directory.getAbsolutePath());
683: 
684:         final List<String> relativizedURLs = new ArrayList<>();
685:         final Path workingDirectory = FileUtils.getCurrentWorkingDirectory();
686:         for (File file : Preconditions.checkNotNull(directory.listFiles())) {
687:             if (!FileUtils.isJarFile(file.toPath())) {
688:                 // any non-JARs are filtered by PackagedProgramRetrieverImpl
689:                 continue;
690:             }
691: 
692:             Path relativePath = FileUtils.relativizePath(workingDirectory, file.toPath());
693:             relativizedURLs.add(FileUtils.toURL(relativePath).toString());
694:         }
695: 
696:         return relativizedURLs;
697:     }
