653:     private ExecutionPlan retrieveJobGraph(
654:             PackagedProgramRetriever retrieverUnderTest, Configuration configuration)
655:             throws FlinkException, ProgramInvocationException, MalformedURLException {
656:         final PackagedProgram packagedProgram = retrieverUnderTest.getPackagedProgram();
657: 
658:         final int defaultParallelism = configuration.get(CoreOptions.DEFAULT_PARALLELISM);
659:         ConfigUtils.encodeCollectionToConfig(
660:                 configuration,
661:                 PipelineOptions.JARS,
662:                 packagedProgram.getJobJarAndDependencies(),
663:                 URL::toString);
664:         ConfigUtils.encodeCollectionToConfig(
665:                 configuration,
666:                 PipelineOptions.CLASSPATHS,
667:                 packagedProgram.getClasspaths(),
668:                 URL::toString);
669: 
670:         final Pipeline pipeline =
671:                 PackagedProgramUtils.getPipelineFromProgram(
672:                         packagedProgram, configuration, defaultParallelism, false);
673:         return PipelineExecutorUtils.getExecutionPlan(
674:                 pipeline, configuration, packagedProgram.getUserCodeClassLoader());
