50: /** An {@link PipelineExecutor} for executing a {@link Pipeline} locally. */
51: @Internal
52: public class LocalExecutor implements PipelineExecutor {
53:     private static final Logger LOG = LoggerFactory.getLogger(LocalExecutor.class);
54:     private final ExecutorService executorService =
55:             Executors.newFixedThreadPool(1, new ExecutorThreadFactory("Flink-LocalExecutor-IO"));
56: 
57:     public static final String NAME = "local";
58: 
59:     private final Configuration configuration;
60:     private final Function<MiniClusterConfiguration, MiniCluster> miniClusterFactory;
61:     private final List<JobStatusChangedListener> jobStatusChangedListeners;
62: 
63:     public static LocalExecutor create(Configuration configuration) {
64:         return new LocalExecutor(configuration, MiniCluster::new);
65:     }
66: 
67:     public static LocalExecutor createWithFactory(
68:             Configuration configuration,
69:             Function<MiniClusterConfiguration, MiniCluster> miniClusterFactory) {
70:         return new LocalExecutor(configuration, miniClusterFactory);
71:     }
72: 
73:     private LocalExecutor(
74:             Configuration configuration,
75:             Function<MiniClusterConfiguration, MiniCluster> miniClusterFactory) {
76:         this.configuration = configuration;
77:         this.miniClusterFactory = miniClusterFactory;
78:         this.jobStatusChangedListeners =
79:                 JobStatusChangedListenerUtils.createJobStatusChangedListeners(
80:                         Thread.currentThread().getContextClassLoader(),
81:                         configuration,
82:                         executorService);
83:     }
84: 
85:     @Override
86:     public CompletableFuture<JobClient> execute(
87:             Pipeline pipeline, Configuration configuration, ClassLoader userCodeClassloader)
88:             throws Exception {
89:         checkNotNull(pipeline);
90:         checkNotNull(configuration);
91: 
92:         Configuration effectiveConfig = new Configuration();
93:         effectiveConfig.addAll(this.configuration);
94:         effectiveConfig.addAll(configuration);
95: 
96:         // we only support attached execution with the local executor.
97:         checkState(configuration.get(DeploymentOptions.ATTACHED));
98: 
99:         final ExecutionPlan jobGraph = getJobGraph(pipeline, effectiveConfig, userCodeClassloader);
100: 
101:         return PerJobMiniClusterFactory.createWithFactory(effectiveConfig, miniClusterFactory)
102:                 .submitJob(jobGraph, userCodeClassloader)
103:                 .whenComplete(
104:                         (ignored, throwable) -> {
105:                             if (throwable == null) {
106:                                 PipelineExecutorUtils.notifyJobStatusListeners(
107:                                         pipeline, jobGraph, jobStatusChangedListeners);
108:                             } else {
109:                                 LOG.error(
110:                                         "Failed to submit job graph to local mini cluster.",
111:                                         throwable);
112:                             }
113:                         });
114:     }
115: 
116:     private ExecutionPlan getJobGraph(
117:             Pipeline pipeline, Configuration configuration, ClassLoader userCodeClassloader)
118:             throws MalformedURLException {
119:         // This is a quirk in how LocalEnvironment used to work. It sets the default parallelism
120:         // to <num taskmanagers> * <num task slots>. Might be questionable but we keep the behaviour
121:         // for now.
122:         if (pipeline instanceof Plan) {
123:             Plan plan = (Plan) pipeline;
124:             final int slotsPerTaskManager =
125:                     configuration.get(
126:                             TaskManagerOptions.NUM_TASK_SLOTS, plan.getMaximumParallelism());
127:             final int numTaskManagers =
128:                     configuration.get(TaskManagerOptions.MINI_CLUSTER_NUM_TASK_MANAGERS);
129: 
130:             plan.setDefaultParallelism(slotsPerTaskManager * numTaskManagers);
131:         }
132: 
133:         return PipelineExecutorUtils.getExecutionPlan(pipeline, configuration, userCodeClassloader);
134:     }
135: }
