1064:     public CompletableFuture<JobSubmissionResult> submitJob(org.apache.flink.streaming.api.graph.ExecutionPlan executionPlan) {
1065:         // When MiniCluster uses the local RPC, the provided ExecutionPlan is passed directly to the
1066:         // Dispatcher. This means that any mutations to the JG can affect the Dispatcher behaviour,
1067:         // so we rather clone it to guard against this.
1068:         final org.apache.flink.streaming.api.graph.ExecutionPlan clonedExecutionPlan = InstantiationUtil.cloneUnchecked(executionPlan);
1069:         checkRestoreModeForChangelogStateBackend(clonedExecutionPlan);
1070:         final CompletableFuture<DispatcherGateway> dispatcherGatewayFuture =
1071:                 getDispatcherGatewayFuture();
1072:         final CompletableFuture<InetSocketAddress> blobServerAddressFuture =
1073:                 createBlobServerAddress(dispatcherGatewayFuture);
1074:         final CompletableFuture<Void> jarUploadFuture =
1075:                 uploadAndSetJobFiles(blobServerAddressFuture, clonedExecutionPlan);
1076:         final CompletableFuture<Acknowledge> acknowledgeCompletableFuture =
1077:                 jarUploadFuture
1078:                         .thenCombine(
1079:                                 dispatcherGatewayFuture,
1080:                                 (Void ack, DispatcherGateway dispatcherGateway) ->
1081:                                         dispatcherGateway.submitJob(
1082:                                                 clonedExecutionPlan, rpcTimeout))
1083:                         .thenCompose(Function.identity());
1084:         return acknowledgeCompletableFuture.thenApply(
1085:                 (Acknowledge ignored) -> new JobSubmissionResult(clonedExecutionPlan.getJobID()));
1086:     }
