1290:                             } catch (Exception e) {
1291:                                 exception = ExceptionUtils.firstOrSuppressed(e, exception);
1292:                             }
1293: 
1294:                             clusterRestEndpointLeaderRetrievalService = null;
1295:                         }
1296:                     }
1297: 
1298:                     if (exception != null) {
1299:                         throw exception;
1300:                     }
1301:                 });
