312:     /**
313:      * Starts the mini cluster, based on the configured properties.
314:      *
315:      * @throws Exception This method passes on any exception that occurs during the startup of the
316:      *     mini cluster.
317:      */
318:     public void start() throws Exception {
319:         synchronized (lock) {
320:             checkState(!running, "MiniCluster is already running");
321: 
322:             LOG.info("Starting Flink Mini Cluster");
323:             LOG.debug("Using configuration {}", miniClusterConfiguration);
324: 
325:             final Configuration configuration = miniClusterConfiguration.getConfiguration();
326:             final boolean useSingleRpcService =
327:                     miniClusterConfiguration.getRpcServiceSharing() == RpcServiceSharing.SHARED;
328: 
329:             try {
330:                 workingDirectory =
331:                         WorkingDirectory.create(
332:                                 ClusterEntrypointUtils.generateWorkingDirectoryFile(
333:                                         configuration,
334:                                         Optional.of(PROCESS_WORKING_DIR_BASE),
335:                                         "minicluster_" + ResourceID.generate()));
336: 
337:                 initializeIOFormatClasses(configuration);
338: 
339:                 rpcSystem = rpcSystemSupplier.get();
340: 
341:                 LOG.info("Starting Metrics Registry");
342:                 metricRegistry =
343:                         createMetricRegistry(
344:                                 configuration,
345:                                 rpcSystem.deref().getMaximumMessageSizeInBytes(configuration));
346: 
347:                 // bring up all the RPC services
348:                 LOG.info("Starting RPC Service(s)");
349: 
350:                 final RpcServiceFactory dispatcherResourceManagerComponentRpcServiceFactory;
351:                 final RpcService metricQueryServiceRpcService;
352: 
353:                 if (useSingleRpcService) {
354:                     // we always need the 'commonRpcService' for auxiliary calls
355:                     commonRpcService = createLocalRpcService(configuration, rpcSystem.deref());
356:                     final CommonRpcServiceFactory commonRpcServiceFactory =
357:                             new CommonRpcServiceFactory(commonRpcService);
358:                     taskManagerRpcServiceFactory = commonRpcServiceFactory;
359:                     dispatcherResourceManagerComponentRpcServiceFactory = commonRpcServiceFactory;
360:                     metricQueryServiceRpcService =
361:                             MetricUtils.startLocalMetricsRpcService(
362:                                     configuration, rpcSystem.deref());
363:                 } else {
364: 
365:                     // start a new service per component, possibly with custom bind addresses
366:                     final String jobManagerExternalAddress =
367:                             miniClusterConfiguration.getJobManagerExternalAddress();
368:                     final String taskManagerExternalAddress =
369:                             miniClusterConfiguration.getTaskManagerExternalAddress();
370:                     final String jobManagerExternalPortRange =
371:                             miniClusterConfiguration.getJobManagerExternalPortRange();
372:                     final String taskManagerExternalPortRange =
373:                             miniClusterConfiguration.getTaskManagerExternalPortRange();
374:                     final String jobManagerBindAddress =
375:                             miniClusterConfiguration.getJobManagerBindAddress();
376:                     final String taskManagerBindAddress =
377:                             miniClusterConfiguration.getTaskManagerBindAddress();
378: 
379:                     dispatcherResourceManagerComponentRpcServiceFactory =
380:                             new DedicatedRpcServiceFactory(
381:                                     configuration,
382:                                     jobManagerExternalAddress,
383:                                     jobManagerExternalPortRange,
384:                                     jobManagerBindAddress,
385:                                     rpcSystem.deref());
386:                     taskManagerRpcServiceFactory =
387:                             new DedicatedRpcServiceFactory(
388:                                     configuration,
389:                                     taskManagerExternalAddress,
390:                                     taskManagerExternalPortRange,
391:                                     taskManagerBindAddress,
392:                                     rpcSystem.deref());
393: 
394:                     // we always need the 'commonRpcService' for auxiliary calls
395:                     // bind to the JobManager address with port 0
396:                     commonRpcService =
397:                             createRemoteRpcService(
398:                                     configuration, jobManagerBindAddress, 0, rpcSystem.deref());
399:                     metricQueryServiceRpcService =
400:                             MetricUtils.startRemoteMetricsRpcService(
401:                                     configuration,
402:                                     commonRpcService.getAddress(),
403:                                     null,
404:                                     rpcSystem.deref());
405:                 }
406: 
407:                 metricRegistry.startQueryService(metricQueryServiceRpcService, null);
408: 
409:                 processMetricGroup =
410:                         MetricUtils.instantiateProcessMetricGroup(
411:                                 metricRegistry,
412:                                 RpcUtils.getHostname(commonRpcService),
413:                                 ConfigurationUtils.getSystemResourceMetricsProbingInterval(
414:                                         configuration));
415: 
416:                 ioExecutor =
417:                         Executors.newFixedThreadPool(
418:                                 ClusterEntrypointUtils.getPoolSize(configuration),
419:                                 new ExecutorThreadFactory("mini-cluster-io"));
420: 
421:                 delegationTokenManager =
422:                         DefaultDelegationTokenManagerFactory.create(
423:                                 configuration,
424:                                 miniClusterConfiguration.getPluginManager(),
425:                                 commonRpcService.getScheduledExecutor(),
426:                                 ioExecutor);
427:                 // Obtaining delegation tokens and propagating them to the local JVM receivers in a
428:                 // one-time fashion is required because BlobServer may connect to external file
429:                 // systems
430:                 delegationTokenManager.obtainDelegationTokens();
431: 
432:                 delegationTokenReceiverRepository =
433:                         new DelegationTokenReceiverRepository(
434:                                 configuration, miniClusterConfiguration.getPluginManager());
435: 
436:                 haServicesFactory = createHighAvailabilityServicesFactory(configuration);
437: 
438:                 haServices = createHighAvailabilityServices(configuration, ioExecutor);
439: 
440:                 blobServer =
441:                         BlobUtils.createBlobServer(
442:                                 configuration,
443:                                 Reference.borrowed(workingDirectory.getBlobStorageDirectory()),
444:                                 haServices.createBlobStore());
445:                 blobServer.start();
446: 
447:                 heartbeatServices = HeartbeatServices.fromConfiguration(configuration);
448: 
449:                 blobCacheService =
450:                         BlobUtils.createBlobCacheService(
451:                                 configuration,
452:                                 Reference.borrowed(workingDirectory.getBlobStorageDirectory()),
453:                                 haServices.createBlobStore(),
454:                                 new InetSocketAddress(
455:                                         InetAddress.getLocalHost(), blobServer.getPort()));
456: 
457:                 startTaskManagers();
458: 
459:                 MetricQueryServiceRetriever metricQueryServiceRetriever =
460:                         new RpcMetricQueryServiceRetriever(
461:                                 metricRegistry.getMetricQueryServiceRpcService());
462: 
463:                 setupDispatcherResourceManagerComponents(
464:                         configuration,
465:                         dispatcherResourceManagerComponentRpcServiceFactory,
466:                         metricQueryServiceRetriever);
467: 
468:                 resourceManagerLeaderRetriever = haServices.getResourceManagerLeaderRetriever();
469:                 dispatcherLeaderRetriever = haServices.getDispatcherLeaderRetriever();
470:                 clusterRestEndpointLeaderRetrievalService =
471:                         haServices.getClusterRestEndpointLeaderRetriever();
472: 
473:                 dispatcherGatewayRetriever =
474:                         new RpcGatewayRetriever<>(
475:                                 commonRpcService,
476:                                 DispatcherGateway.class,
477:                                 DispatcherId::fromUuid,
478:                                 new ExponentialBackoffRetryStrategy(
479:                                         21, Duration.ofMillis(5L), Duration.ofMillis(20L)));
480:                 resourceManagerGatewayRetriever =
481:                         new RpcGatewayRetriever<>(
482:                                 commonRpcService,
483:                                 ResourceManagerGateway.class,
484:                                 ResourceManagerId::fromUuid,
485:                                 new ExponentialBackoffRetryStrategy(
486:                                         21, Duration.ofMillis(5L), Duration.ofMillis(20L)));
487:                 webMonitorLeaderRetriever = new LeaderRetriever();
488: 
489:                 resourceManagerLeaderRetriever.start(resourceManagerGatewayRetriever);
490:                 dispatcherLeaderRetriever.start(dispatcherGatewayRetriever);
491:                 clusterRestEndpointLeaderRetrievalService.start(webMonitorLeaderRetriever);
492:             } catch (Exception e) {
493:                 // cleanup everything
494:                 try {
495:                     close();
496:                 } catch (Exception ee) {
497:                     e.addSuppressed(ee);
498:                 }
499:                 throw e;
500:             }
501: 
502:             // create a new termination future
503:             terminationFuture = new CompletableFuture<>();
504: 
505:             // now officially mark this as running
506:             running = true;
507: 
508:             LOG.info("Flink Mini Cluster started successfully");
509:         }
510:     }
