512:     @GuardedBy("lock")
513:     private void setupDispatcherResourceManagerComponents(
514:             Configuration configuration,
515:             RpcServiceFactory dispatcherResourceManagerComponentRpcServiceFactory,
516:             MetricQueryServiceRetriever metricQueryServiceRetriever)
517:             throws Exception {
518:         dispatcherResourceManagerComponents.addAll(
519:                 createDispatcherResourceManagerComponents(
520:                         configuration,
521:                         dispatcherResourceManagerComponentRpcServiceFactory,
522:                         blobServer,
523:                         heartbeatServices,
524:                         delegationTokenManager,
525:                         metricRegistry,
526:                         metricQueryServiceRetriever,
527:                         new ShutDownFatalErrorHandler()));
528: 
529:         FutureUtils.completeAll(
530:                         dispatcherResourceManagerComponents.stream()
531:                                 .map(DispatcherResourceManagerComponent::getShutDownFuture)
532:                                 .collect(Collectors.toList()))
533:                 .whenComplete((ignored, exception) -> closeAsync());
534:     }
