582:     private HighAvailabilityServicesFactory createHighAvailabilityServicesFactory(
583:             Configuration configuration) {
584:         final HaServices customMiniClusterHaServicesMode = miniClusterConfiguration.getHaServices();
585:         if (customMiniClusterHaServicesMode == HaServices.WITH_LEADERSHIP_CONTROL) {
586:             // special feature of MiniClusters to allow the control of leadership
587:             // EmbeddedLeaderElection requires a single instance for leader election across multiple
588:             // JobManager instances on the same JVM (after FLINK-24038 was introduced); therefore,
589:             // SingletonHighAvailabilityServicesFactory is utilized here
590:             return new SingletonHighAvailabilityServicesFactory(
591:                     (config, embeddedLeaderElectionExecutor) ->
592:                             new EmbeddedHaServicesWithLeadershipControl(
593:                                     embeddedLeaderElectionExecutor));
594:         } else if (customMiniClusterHaServicesMode != HaServices.CONFIGURED) {
595:             throw new IllegalConfigurationException(
596:                     "Unknown HA Services Mode configured in MiniCluster configuration: "
597:                             + customMiniClusterHaServicesMode);
598:         }
599: 
600:         final HighAvailabilityMode highAvailabilityMode =
601:                 HighAvailabilityMode.fromConfig(configuration);
602:         if (highAvailabilityMode == HighAvailabilityMode.NONE) {
603:             // basic EmbeddedLeaderElection requires a single instance for leader election across
604:             // multiple JobManager instances on the same JVM (after FLINK-24038 was introduced);
605:             // therefore, SingletonHighAvailabilityServicesFactory is utilized here
606:             return new SingletonHighAvailabilityServicesFactory(
607:                     (config, embeddedLeaderElectionExecutor) ->
608:                             new EmbeddedHaServices(embeddedLeaderElectionExecutor));
609:         } else {
610:             return new RegularHighAvailabilityServicesFactory();
611:         }
612:     }
