641:     /**
642:      * Shuts down the mini cluster, failing all currently executing jobs. The mini cluster can be
643:      * started again by calling the {@link #start()} method again.
644:      *
645:      * <p>This method shuts down all started services and components, even if an exception occurs in
646:      * the process of shutting down some component.
647:      *
648:      * @return Future which is completed once the MiniCluster has been completely shut down
649:      */
650:     @Override
651:     public CompletableFuture<Void> closeAsync() {
652:         return closeInternal(true);
653:     }
654: 
655:     public CompletableFuture<Void> closeAsyncWithoutCleaningHighAvailabilityData() {
656:         return closeInternal(false);
657:     }
658: 
659:     private CompletableFuture<Void> closeInternal(boolean cleanupHaData) {
660:         synchronized (lock) {
661:             if (running) {
662:                 LOG.info("Shutting down Flink Mini Cluster");
663:                 try {
664:                     final long shutdownTimeoutMillis =
665:                             miniClusterConfiguration
666:                                     .getConfiguration()
667:                                     .get(ClusterOptions.CLUSTER_SERVICES_SHUTDOWN_TIMEOUT)
668:                                     .toMillis();
669:                     final int numComponents = 2 + miniClusterConfiguration.getNumTaskManagers();
670:                     final Collection<CompletableFuture<Void>> componentTerminationFutures =
671:                             new ArrayList<>(numComponents);
672: 
673:                     componentTerminationFutures.addAll(terminateTaskManagers());
674: 
675:                     componentTerminationFutures.add(shutDownResourceManagerComponents());
676: 
677:                     final FutureUtils.ConjunctFuture<Void> componentsTerminationFuture =
678:                             FutureUtils.completeAll(componentTerminationFutures);
679: 
680:                     final CompletableFuture<Void> metricSystemTerminationFuture =
681:                             FutureUtils.composeAfterwards(
682:                                     componentsTerminationFuture, this::closeMetricSystem);
683: 
684:                     final CompletableFuture<Void> rpcServicesTerminationFuture =
685:                             FutureUtils.composeAfterwards(
686:                                     metricSystemTerminationFuture, this::terminateRpcServices);
687: 
688:                     final CompletableFuture<Void> remainingServicesTerminationFuture =
689:                             FutureUtils.runAfterwards(
690:                                     rpcServicesTerminationFuture,
691:                                     () -> terminateMiniClusterServices(cleanupHaData));
692: 
693:                     final CompletableFuture<Void> executorsTerminationFuture =
694:                             FutureUtils.composeAfterwards(
695:                                     remainingServicesTerminationFuture,
696:                                     () -> terminateExecutors(shutdownTimeoutMillis));
697: 
698:                     final CompletableFuture<Void> deleteDirectoriesFuture =
699:                             FutureUtils.runAfterwards(
700:                                     executorsTerminationFuture, this::deleteDirectories);
701: 
702:                     deleteDirectoriesFuture.whenComplete(
703:                             (Void ignored, Throwable throwable) -> {
704:                                 if (throwable != null) {
705:                                     terminationFuture.completeExceptionally(
706:                                             ExceptionUtils.stripCompletionException(throwable));
707:                                 } else {
708:                                     terminationFuture.complete(null);
709:                                 }
710:                             });
711:                 } finally {
712:                     running = false;
713:                 }
714:             }
715: 
716:             return terminationFuture;
717:         }
718:     }
719: 
720:     private CompletableFuture<Void> closeMetricSystem() {
721:         synchronized (lock) {
722:             final ArrayList<CompletableFuture<Void>> terminationFutures = new ArrayList<>(2);
723: 
724:             if (processMetricGroup != null) {
725:                 processMetricGroup.close();
726:                 processMetricGroup = null;
727:             }
728: 
729:             // metrics shutdown
730:             if (metricRegistry != null) {
731:                 terminationFutures.add(metricRegistry.closeAsync());
732:                 metricRegistry = null;
733:             }
734: 
735:             return FutureUtils.completeAll(terminationFutures);
736:         }
737:     }
