739:     @GuardedBy("lock")
740:     private void startTaskManagers() throws Exception {
741:         final int numTaskManagers = miniClusterConfiguration.getNumTaskManagers();
742: 
743:         LOG.info("Starting {} TaskManager(s)", numTaskManagers);
744: 
745:         for (int i = 0; i < numTaskManagers; i++) {
746:             startTaskManager();
747:         }
748:     }
