750:     /**
751:      * Starts additional TaskManager process.
752:      *
753:      * <p>When the MiniCluster starts up, it always starts {@link
754:      * MiniClusterConfiguration#getNumTaskManagers} TaskManagers. All TaskManagers are indexed from
755:      * 0 to the number of TaskManagers, started so far, minus one. This method starts a TaskManager
756:      * with the next index which is the number of TaskManagers, started so far. The index always
757:      * increases with each new started TaskManager. The indices of terminated TaskManagers are not
758:      * reused after {@link #terminateTaskManager(int)}.
759:      */
760:     public void startTaskManager() throws Exception {
761:         synchronized (lock) {
762:             final Configuration configuration = miniClusterConfiguration.getConfiguration();
763: 
764:             final TaskExecutor taskExecutor =
765:                     TaskManagerRunner.startTaskManager(
766:                             configuration,
767:                             new ResourceID(UUID.randomUUID().toString()),
768:                             taskManagerRpcServiceFactory.createRpcService(),
769:                             haServices,
770:                             heartbeatServices,
771:                             metricRegistry,
772:                             blobCacheService,
773:                             useLocalCommunication(),
774:                             ExternalResourceInfoProvider.NO_EXTERNAL_RESOURCES,
775:                             workingDirectory.createSubWorkingDirectory("tm_" + taskManagers.size()),
776:                             taskManagerTerminatingFatalErrorHandlerFactory.create(
777:                                     taskManagers.size()),
778:                             delegationTokenReceiverRepository);
779: 
780:             taskExecutor.start();
781:             taskManagers.add(taskExecutor);
782:         }
783:     }
