1006:     /**
1007:      * This method executes a job in detached mode. The method returns immediately after the job has
1008:      * been added to the
1009:      *
1010:      * @param executionPlan The Flink job to execute
1011:      * @throws JobExecutionException Thrown if anything went amiss during initial job launch, or if
1012:      *     the job terminally failed.
1013:      */
1014:     public void runDetached(ExecutionPlan executionPlan) throws JobExecutionException, InterruptedException {
1015:         checkNotNull(executionPlan, "job is null");
1016: 
1017:         final CompletableFuture<JobSubmissionResult> submissionFuture = submitJob(executionPlan);
1018: 
1019:         try {
1020:             submissionFuture.get();
1021:         } catch (ExecutionException e) {
1022:             throw new JobExecutionException(
1023:                     executionPlan.getJobID(), ExceptionUtils.stripExecutionException(e));
1024:         }
1025:     }
1026: 
1027:     /**
1028:      * This method runs a job in blocking mode. The method returns only after the job completed
1029:      * successfully, or after it failed terminally.
1030:      *
1031:      * @param job The Flink job to execute
1032:      * @return The result of the job execution
1033:      * @throws JobExecutionException Thrown if anything went amiss during initial job launch, or if
1034:      *     the job terminally failed.
1035:      */
1036:     public JobExecutionResult executeJobBlocking(ExecutionPlan job)
1037:             throws JobExecutionException, InterruptedException {
1038:         checkNotNull(job, "job is null");
1039: 
1040:         final CompletableFuture<JobSubmissionResult> submissionFuture = submitJob(job);
1041: 
1042:         final CompletableFuture<JobResult> jobResultFuture =
1043:                 submissionFuture.thenCompose(
1044:                         (JobSubmissionResult ignored) -> requestJobResult(job.getJobID()));
1045: 
1046:         final JobResult jobResult;
1047: 
1048:         try {
1049:             jobResult = jobResultFuture.get();
1050:         } catch (ExecutionException e) {
1051:             throw new JobExecutionException(
1052:                     job.getJobID(),
1053:                     "Could not retrieve JobResult.",
1054:                     ExceptionUtils.stripExecutionException(e));
1055:         }
1056: 
1057:         try {
1058:             return jobResult.toJobExecutionResult(Thread.currentThread().getContextClassLoader());
1059:         } catch (IOException | ClassNotFoundException e) {
1060:             throw new JobExecutionException(job.getJobID(), e);
1061:         }
1062:     }
