1088:     // HACK: temporary hack to make the randomized changelog state backend tests work with forced
1089:     // full snapshots. This option should be removed once changelog state backend supports forced
1090:     // full snapshots
1091:     private void checkRestoreModeForChangelogStateBackend(org.apache.flink.streaming.api.graph.ExecutionPlan executionPlan) {
1092:         final SavepointRestoreSettings savepointRestoreSettings =
1093:                 executionPlan.getSavepointRestoreSettings();
1094:         if (overrideRestoreModeForChangelogStateBackend
1095:                 && savepointRestoreSettings.getRecoveryClaimMode() == RecoveryClaimMode.NO_CLAIM) {
1096:             final Configuration conf = new Configuration();
1097:             SavepointRestoreSettings.toConfiguration(savepointRestoreSettings, conf);
1098:             conf.set(StateRecoveryOptions.RESTORE_MODE, RecoveryClaimMode.LEGACY);
1099:             executionPlan.setSavepointRestoreSettings(
1100:                     SavepointRestoreSettings.fromConfiguration(conf));
1101:         }
1102:     }
