1304:     private void terminateMiniClusterServices(boolean cleanupHaData) throws Exception {
1305:         // collect the first exception, but continue and add all successive
1306:         // exceptions as suppressed
1307:         Exception exception = null;
1308: 
1309:         synchronized (lock) {
1310:             if (blobCacheService != null) {
1311:                 try {
1312:                     blobCacheService.close();
1313:                 } catch (Exception e) {
1314:                     exception = ExceptionUtils.firstOrSuppressed(e, exception);
1315:                 }
1316:                 blobCacheService = null;
1317:             }
1318: 
1319:             // shut down the blob server
1320:             if (blobServer != null) {
1321:                 try {
1322:                     blobServer.close();
1323:                 } catch (Exception e) {
1324:                     exception = ExceptionUtils.firstOrSuppressed(e, exception);
1325:                 }
1326:                 blobServer = null;
1327:             }
1328: 
1329:             // shut down high-availability services
1330:             if (haServices != null) {
1331:                 haServices.closeWithOptionalClean(cleanupHaData);
1332:                 haServices = null;
1333:             }
1334: 
1335:             try {
1336:                 if (rpcSystem.isOwned()) {
1337:                     rpcSystem.deref().close();
1338:                 }
1339:             } catch (Exception e) {
1340:                 exception = ExceptionUtils.firstOrSuppressed(e, exception);
1341:             }
1342: 
1343:             if (exception != null) {
1344:                 throw exception;
1345:             }
1346:         }
1347:     }
