474:     private static Class<?> loadMainClass(String className, ClassLoader cl)
475:             throws ProgramInvocationException {
476:         ClassLoader contextCl = null;
477:         try {
478:             contextCl = Thread.currentThread().getContextClassLoader();
479:             Thread.currentThread().setContextClassLoader(cl);
480:             return Class.forName(className, false, cl);
481:         } catch (ClassNotFoundException e) {
482:             throw new ProgramInvocationException(
483:                     "The program's entry point class '"
484:                             + className
485:                             + "' was not found in the jar file.",
486:                     e);
487:         } catch (ExceptionInInitializerError e) {
488:             throw new ProgramInvocationException(
489:                     "The program's entry point class '"
490:                             + className
491:                             + "' threw an error during initialization.",
492:                     e);
493:         } catch (LinkageError e) {
494:             throw new ProgramInvocationException(
495:                     "The program's entry point class '"
496:                             + className
497:                             + "' could not be loaded due to a linkage failure.",
498:                     e);
499:         } catch (Throwable t) {
500:             throw new ProgramInvocationException(
501:                     "The program's entry point class '"
502:                             + className
503:                             + "' caused an exception during initialization: "
504:                             + t.getMessage(),
505:                     t);
506:         } finally {
507:             if (contextCl != null) {
508:                 Thread.currentThread().setContextClassLoader(contextCl);
509:             }
510:         }
511:     }
