383:     private static String getEntryPointClassNameFromJar(URL jarFile)
384:             throws ProgramInvocationException {
385:         JarFile jar;
386:         Manifest manifest;
387:         String className;
388: 
389:         // Open jar file
390:         try {
391:             jar = new JarFile(new File(jarFile.toURI()));
392:         } catch (URISyntaxException use) {
393:             throw new ProgramInvocationException(
394:                     "Invalid file path '" + jarFile.getPath() + "'", use);
395:         } catch (IOException ioex) {
396:             throw new ProgramInvocationException(
397:                     "Error while opening jar file '"
398:                             + jarFile.getPath()
399:                             + "'. "
400:                             + ioex.getMessage(),
401:                     ioex);
402:         }
403: 
404:         // jar file must be closed at the end
405:         try {
406:             // Read from jar manifest
407:             try {
408:                 manifest = jar.getManifest();
409:             } catch (IOException ioex) {
410:                 throw new ProgramInvocationException(
411:                         "The Manifest in the jar file could not be accessed '"
412:                                 + jarFile.getPath()
413:                                 + "'. "
414:                                 + ioex.getMessage(),
415:                         ioex);
416:             }
417: 
418:             if (manifest == null) {
419:                 throw new ProgramInvocationException(
420:                         "No manifest found in jar file '"
421:                                 + jarFile.getPath()
422:                                 + "'. The manifest is need to point to the program's main class.");
423:             }
424: 
425:             Attributes attributes = manifest.getMainAttributes();
426: 
427:             // check for a "program-class" entry first
428:             className = attributes.getValue(PackagedProgram.MANIFEST_ATTRIBUTE_ASSEMBLER_CLASS);
429:             if (className != null) {
430:                 return className;
431:             }
432: 
433:             // check for a main class
434:             className = attributes.getValue(PackagedProgram.MANIFEST_ATTRIBUTE_MAIN_CLASS);
435:             if (className != null) {
436:                 return className;
437:             } else {
438:                 throw new ProgramInvocationException(
439:                         "Neither a '"
440:                                 + MANIFEST_ATTRIBUTE_MAIN_CLASS
441:                                 + "', nor a '"
442:                                 + MANIFEST_ATTRIBUTE_ASSEMBLER_CLASS
443:                                 + "' entry was found in the jar file.");
444:             }
445:         } finally {
446:             try {
447:                 jar.close();
448:             } catch (Throwable t) {
449:                 throw new ProgramInvocationException(
450:                         "Could not close the JAR file: " + t.getMessage(), t);
451:             }
452:         }
453:     }
