513:     /**
514:      * Takes all JAR files that are contained in this program's JAR file and extracts them to the
515:      * system's temp directory.
516:      *
517:      * @return The file names of the extracted temporary files.
518:      * @throws ProgramInvocationException Thrown, if the extraction process failed.
519:      */
520:     public static List<File> extractContainedLibraries(URL jarFile)
521:             throws ProgramInvocationException {
522:         try (final JarFile jar = new JarFile(new File(jarFile.toURI()))) {
523: 
524:             final List<JarEntry> containedJarFileEntries = getContainedJarEntries(jar);
525:             if (containedJarFileEntries.isEmpty()) {
526:                 return Collections.emptyList();
527:             }
528: 
529:             final List<File> extractedTempLibraries =
530:                     new ArrayList<>(containedJarFileEntries.size());
531:             boolean incomplete = true;
532: 
533:             try {
534:                 final Random rnd = new Random();
535:                 final byte[] buffer = new byte[4096];
536: 
537:                 for (final JarEntry entry : containedJarFileEntries) {
538:                     // '/' as in case of zip, jar
539:                     // java.util.zip.ZipEntry#isDirectory always looks only for '/' not for
540:                     // File.separator
541:                     final String name = entry.getName().replace('/', '_');
542:                     final File tempFile = copyLibToTempFile(name, rnd, jar, entry, buffer);
543:                     extractedTempLibraries.add(tempFile);
544:                 }
545: 
546:                 incomplete = false;
547:             } finally {
548:                 if (incomplete) {
549:                     deleteExtractedLibraries(extractedTempLibraries);
550:                 }
551:             }
552: 
553:             return extractedTempLibraries;
554:         } catch (Throwable t) {
555:             throw new ProgramInvocationException(
556:                     "Unknown I/O error while extracting contained jar files.", t);
557:         }
558:     }
559: 
560:     private static File copyLibToTempFile(
561:             String name, Random rnd, JarFile jar, JarEntry input, byte[] buffer)
562:             throws ProgramInvocationException {
563:         final File output = createTempFile(rnd, input, name);
564:         try (final OutputStream out = new FileOutputStream(output);
565:                 final InputStream in = new BufferedInputStream(jar.getInputStream(input))) {
566:             int numRead = 0;
567:             while ((numRead = in.read(buffer)) != -1) {
568:                 out.write(buffer, 0, numRead);
569:             }
570:             return output;
571:         } catch (IOException e) {
572:             throw new ProgramInvocationException(
573:                     "An I/O error occurred while extracting nested library '"
574:                             + input.getName()
575:                             + "' to temporary file '"
576:                             + output.getAbsolutePath()
577:                             + "'.");
578:         }
579:     }
580: 
581:     private static File createTempFile(Random rnd, JarEntry entry, String name)
582:             throws ProgramInvocationException {
583:         try {
584:             final File tempFile = File.createTempFile(rnd.nextInt(Integer.MAX_VALUE) + "_", name);
585:             tempFile.deleteOnExit();
586:             return tempFile;
587:         } catch (IOException e) {
588:             throw new ProgramInvocationException(
589:                     "An I/O error occurred while creating temporary file to extract nested library '"
590:                             + entry.getName()
591:                             + "'.",
592:                     e);
593:         }
594:     }
595: 
596:     private static List<JarEntry> getContainedJarEntries(JarFile jar) {
597:         return jar.stream()
598:                 .filter(
599:                         jarEntry -> {
600:                             final String name = jarEntry.getName();
601:                             return name.length() > 8
602:                                     && name.startsWith("lib/")
603:                                     && name.endsWith(".jar");
604:                         })
605:                 .collect(Collectors.toList());
606:     }
607: 
608:     private static void deleteExtractedLibraries(List<File> tempLibraries) {
609:         for (File f : tempLibraries) {
610:             f.delete();
611:         }
612:     }
