188:     protected void initialize(
189:             int executionHistorySizeLimit,
190:             Time timeout,
191:             long createTimestamp,
192:             SubtaskAttemptNumberStore initialAttemptCounts)
193:             throws JobException {
194: 
195:         checkState(parallelismInfo.getParallelism() > 0);
196:         checkState(!isInitialized());
197: 
198:         this.taskVertices = new ExecutionVertex[parallelismInfo.getParallelism()];
199: 
200:         this.inputs = new ArrayList<>(jobVertex.getInputs().size());
201: 
202:         // create the intermediate results
203:         this.producedDataSets =
204:                 new IntermediateResult[jobVertex.getNumberOfProducedIntermediateDataSets()];
205: 
206:         for (int i = 0; i < jobVertex.getProducedDataSets().size(); i++) {
207:             final IntermediateDataSet result = jobVertex.getProducedDataSets().get(i);
208: 
209:             this.producedDataSets[i] =
210:                     new IntermediateResult(
211:                             result,
212:                             this,
213:                             this.parallelismInfo.getParallelism(),
214:                             result.getResultType());
215:         }
216: 
217:         // create all task vertices
218:         for (int i = 0; i < this.parallelismInfo.getParallelism(); i++) {
219:             ExecutionVertex vertex =
220:                     createExecutionVertex(
221:                             this,
222:                             i,
223:                             producedDataSets,
224:                             timeout,
225:                             createTimestamp,
226:                             executionHistorySizeLimit,
227:                             initialAttemptCounts.getAttemptCount(i));
228: 
229:             this.taskVertices[i] = vertex;
230:         }
231: 
232:         // sanity check for the double referencing between intermediate result partitions and
233:         // execution vertices
234:         for (IntermediateResult ir : this.producedDataSets) {
235:             if (ir.getNumberOfAssignedPartitions() != this.parallelismInfo.getParallelism()) {
236:                 throw new RuntimeException(
237:                         "The intermediate result's partitions were not correctly assigned.");
238:             }
239:         }
240: 
241:         // set up the input splits, if the vertex has any
242:         try {
243:             @SuppressWarnings("unchecked")
244:             InputSplitSource<InputSplit> splitSource =
245:                     (InputSplitSource<InputSplit>) jobVertex.getInputSplitSource();
246: 
247:             if (splitSource != null) {
248:                 Thread currentThread = Thread.currentThread();
249:                 ClassLoader oldContextClassLoader = currentThread.getContextClassLoader();
250:                 currentThread.setContextClassLoader(graph.getUserClassLoader());
251:                 try {
252:                     inputSplits =
253:                             splitSource.createInputSplits(this.parallelismInfo.getParallelism());
254: 
255:                     if (inputSplits != null) {
256:                         splitAssigner = splitSource.getInputSplitAssigner(inputSplits);
257:                     }
258:                 } finally {
259:                     currentThread.setContextClassLoader(oldContextClassLoader);
260:                 }
261:             } else {
262:                 inputSplits = null;
263:             }
264:         } catch (Throwable t) {
265:             throw new JobException(
266:                     "Creating the input splits caused an error: " + t.getMessage(), t);
267:         }
268:     }
