41: /**
42:  * Simple container class which contains the raw/managed operator state and key-group state handles
43:  * from all subtasks of an operator and therefore represents the complete state of a logical
44:  * operator.
45:  */
46: public class OperatorState implements CompositeStateHandle {
47: 
48:     private static final long serialVersionUID = -4845578005863201810L;
49: 
50:     /** The id of the operator. */
51:     private final OperatorID operatorIDPair;
52: 
53:     /** The handles to states created by the parallel tasks: subtaskIndex -> subtaskstate. */
54:     private final Map<Integer, OperatorSubtaskState> operatorSubtaskStates;
55: 
56:     /** The state of the operator coordinator. Null, if no such state exists. */
57:     @Nullable private ByteStreamStateHandle coordinatorState;
58: 
59:     /** The parallelism of the operator when it was checkpointed. */
60:     private final int parallelism;
61: 
62:     /**
63:      * The maximum parallelism (for number of KeyGroups) of the operator when the job was first
64:      * created.
65:      */
66:     private final int maxParallelism;
67: 
68:     public OperatorState(OperatorID operatorID, int parallelism, int maxParallelism) {
69:         if (parallelism > maxParallelism) {
70:             throw new IllegalArgumentException(
71:                     String.format(
72:                             "Parallelism %s is not smaller or equal to max parallelism %s.",
73:                             parallelism, maxParallelism));
74:         }
75: 
76:         this.operatorIDPair = operatorID;
77: 
78:         this.operatorSubtaskStates = CollectionUtil.newHashMapWithExpectedSize(parallelism);
79: 
80:         this.parallelism = parallelism;
81:         this.maxParallelism = maxParallelism;
82:     }
83: 
84:     public OperatorID getOperatorID() {
85:         return operatorIDPair;
86:     }
87: 
88:     public boolean isFullyFinished() {
89:         return false;
90:     }
91: 
92:     public void putState(int subtaskIndex, OperatorSubtaskState subtaskState) {
93:         Preconditions.checkNotNull(subtaskState);
94: 
95:         if (subtaskIndex < 0 || subtaskIndex >= parallelism) {
96:             throw new IndexOutOfBoundsException(
97:                     "The given sub task index "
98:                             + subtaskIndex
99:                             + " exceeds the maximum number of sub tasks "
100:                             + operatorSubtaskStates.size());
101:         } else {
102:             operatorSubtaskStates.put(subtaskIndex, subtaskState);
103:         }
104:     }
105: 
106:     public OperatorSubtaskState getState(int subtaskIndex) {
107:         if (subtaskIndex < 0 || subtaskIndex >= parallelism) {
108:             throw new IndexOutOfBoundsException(
109:                     "The given sub task index "
110:                             + subtaskIndex
111:                             + " exceeds the maximum number of sub tasks "
112:                             + operatorSubtaskStates.size());
113:         } else {
114:             return operatorSubtaskStates.get(subtaskIndex);
115:         }
116:     }
117: 
118:     public void setCoordinatorState(@Nullable ByteStreamStateHandle coordinatorState) {
119:         checkState(this.coordinatorState == null, "coordinator state already set");
120:         this.coordinatorState = coordinatorState;
121:     }
122: 
123:     @Nullable
124:     public ByteStreamStateHandle getCoordinatorState() {
125:         return coordinatorState;
126:     }
127: 
128:     public Map<Integer, OperatorSubtaskState> getSubtaskStates() {
129:         return Collections.unmodifiableMap(operatorSubtaskStates);
130:     }
131: 
132:     public Collection<OperatorSubtaskState> getStates() {
133:         return operatorSubtaskStates.values();
134:     }
135: 
136:     public int getNumberCollectedStates() {
137:         return operatorSubtaskStates.size();
138:     }
139: 
140:     public int getParallelism() {
141:         return parallelism;
142:     }
143: 
144:     public int getMaxParallelism() {
145:         return maxParallelism;
146:     }
147: 
148:     public OperatorState copyWithNewOperatorID(OperatorID newOperatorId) {
149:         OperatorState newState = new OperatorState(newOperatorId, parallelism, maxParallelism);
150:         operatorSubtaskStates.forEach(newState::putState);
151:         return newState;
152:     }
153: 
154:     public OperatorState copyAndDiscardInFlightData() {
155:         OperatorState newState = new OperatorState(operatorIDPair, parallelism, maxParallelism);
156: 
157:         for (Map.Entry<Integer, OperatorSubtaskState> originalSubtaskStateEntry :
158:                 operatorSubtaskStates.entrySet()) {
159:             newState.putState(
160:                     originalSubtaskStateEntry.getKey(),
161:                     originalSubtaskStateEntry
162:                             .getValue()
163:                             .toBuilder()
164:                             .setResultSubpartitionState(StateObjectCollection.empty())
165:                             .setInputChannelState(StateObjectCollection.empty())
166:                             .build());
167:         }
168: 
169:         return newState;
170:     }
171: 
172:     public List<StateObject> getDiscardables() {
173:         List<StateObject> toDispose =
174:                 operatorSubtaskStates.values().stream()
175:                         .flatMap(op -> op.getDiscardables().stream())
176:                         .collect(Collectors.toList());
177: 
178:         if (coordinatorState != null) {
179:             toDispose.add(coordinatorState);
180:         }
181:         return toDispose;
182:     }
183: 
184:     @Override
185:     public void discardState() throws Exception {
186:         for (OperatorSubtaskState operatorSubtaskState : operatorSubtaskStates.values()) {
187:             operatorSubtaskState.discardState();
188:         }
189: 
190:         if (coordinatorState != null) {
191:             coordinatorState.discardState();
192:         }
193:     }
194: 
195:     @Override
196:     public void registerSharedStates(SharedStateRegistry sharedStateRegistry, long checkpointID) {
197:         for (OperatorSubtaskState operatorSubtaskState : operatorSubtaskStates.values()) {
198:             operatorSubtaskState.registerSharedStates(sharedStateRegistry, checkpointID);
199:         }
200:     }
201: 
202:     public boolean hasSubtaskStates() {
203:         return operatorSubtaskStates.size() > 0;
204:     }
205: 
206:     @Override
207:     public long getStateSize() {
208:         return streamAllSubHandles().mapToLong(StateObject::getStateSize).sum();
209:     }
210: 
211:     @Override
212:     public void collectSizeStats(StateObjectSizeStatsCollector collector) {
213:         streamAllSubHandles().forEach(handle -> handle.collectSizeStats(collector));
214:     }
215: 
216:     private Stream<StateObject> streamAllSubHandles() {
217:         return Stream.concat(Stream.of(coordinatorState), operatorSubtaskStates.values().stream())
218:                 .filter(Objects::nonNull);
219:     }
220: 
221:     @Override
222:     public long getCheckpointedSize() {
223:         long result = coordinatorState == null ? 0L : coordinatorState.getStateSize();
224: 
225:         for (int i = 0; i < parallelism; i++) {
226:             OperatorSubtaskState operatorSubtaskState = operatorSubtaskStates.get(i);
227:             if (operatorSubtaskState != null) {
228:                 result += operatorSubtaskState.getCheckpointedSize();
229:             }
230:         }
231: 
232:         return result;
233:     }
234: 
235:     @Override
236:     public boolean equals(Object obj) {
237:         if (obj instanceof OperatorState) {
238:             OperatorState other = (OperatorState) obj;
239: 
240:             return operatorIDPair.equals(other.operatorIDPair)
241:                     && parallelism == other.parallelism
242:                     && Objects.equals(coordinatorState, other.coordinatorState)
243:                     && operatorSubtaskStates.equals(other.operatorSubtaskStates);
244:         } else {
245:             return false;
246:         }
247:     }
248: 
249:     @Override
250:     public int hashCode() {
251:         return parallelism + 31 * Objects.hash(operatorIDPair, operatorSubtaskStates);
252:     }
253: 
254:     @Override
255:     public String toString() {
256:         // KvStates are always null in 1.1. Don't print this as it might
257:         // confuse users that don't care about how we store it internally.
258:         return "OperatorState("
259:                 + "operatorID: "
260:                 + operatorIDPair
261:                 + ", parallelism: "
262:                 + parallelism
263:                 + ", maxParallelism: "
264:                 + maxParallelism
265:                 + ", coordinatorState: "
266:                 + (coordinatorState == null ? "(none)" : coordinatorState.getStateSize() + " bytes")
267:                 + ", sub task states: "
268:                 + operatorSubtaskStates.size()
269:                 + ", total size (bytes): "
270:                 + getStateSize()
271:                 + ')';
272:     }
273: }
