275:     /**
276:      * Tries to assign the given slot to the execution. The assignment works only if the Execution
277:      * is in state SCHEDULED. Returns true, if the resource could be assigned.
278:      *
279:      * @param logicalSlot to assign to this execution
280:      * @return true if the slot could be assigned to the execution, otherwise false
281:      */
282:     public boolean tryAssignResource(final LogicalSlot logicalSlot) {
283: 
284:         assertRunningInJobMasterMainThread();
285: 
286:         checkNotNull(logicalSlot);
287: 
288:         // only allow to set the assigned resource in state SCHEDULED or CREATED
289:         // note: we also accept resource assignment when being in state CREATED for testing purposes
290:         if (state == SCHEDULED || state == CREATED) {
291:             if (assignedResource == null) {
292:                 assignedResource = logicalSlot;
293:                 if (logicalSlot.tryAssignPayload(this)) {
294:                     // check for concurrent modification (e.g. cancelling call)
295:                     if ((state == SCHEDULED || state == CREATED)
296:                             && !taskManagerLocationFuture.isDone()) {
297:                         taskManagerLocationFuture.complete(logicalSlot.getTaskManagerLocation());
298:                         assignedAllocationID = logicalSlot.getAllocationId();
299:                         getVertex()
300:                                 .setLatestPriorSlotAllocation(
301:                                         assignedResource.getTaskManagerLocation(),
302:                                         logicalSlot.getAllocationId());
303:                         return true;
304:                     } else {
305:                         // free assigned resource and return false
306:                         assignedResource = null;
307:                         return false;
308:                     }
309:                 } else {
310:                     assignedResource = null;
311:                     return false;
312:                 }
313:             } else {
314:                 // the slot already has another slot assigned
315:                 return false;
316:             }
317:         } else {
318:             // do not allow resource assignment if we are not in state SCHEDULED
319:             return false;
320:         }
321:     }
