456:     private void recoverAttempt(ExecutionAttemptID newId) {
457:         if (!this.attemptId.equals(newId)) {
458:             getVertex().getExecutionGraphAccessor().deregisterExecution(this);
459:             this.attemptId = newId;
460:             getVertex().getExecutionGraphAccessor().registerExecution(this);
461:         }
