464:     /** Recover the execution attempt status after JM failover. */
465:     public void recoverExecution(
466:             ExecutionAttemptID attemptId,
467:             TaskManagerLocation location,
468:             Map<String, Accumulator<?, ?>> userAccumulators,
469:             IOMetrics metrics) {
470:         recoverAttempt(attemptId);
471:         taskManagerLocationFuture.complete(location);
472: 
473:         try {
474:             transitionState(this.state, FINISHED);
475:             finishPartitionsAndUpdateConsumers();
476:             updateAccumulatorsAndMetrics(userAccumulators, metrics);
477:             releaseAssignedResource(null);
478:             vertex.getExecutionGraphAccessor().deregisterExecution(this);
479:         } finally {
480:             vertex.executionFinished(this);
481:         }
482:     }
