809:     private static PartitionInfo createFinishedPartitionInfo(
810:             IntermediateResultPartition consumedPartition) {
811:         IntermediateDataSetID intermediateDataSetID =
812:                 consumedPartition.getIntermediateResult().getId();
813:         ShuffleDescriptor shuffleDescriptor =
814:                 getConsumedPartitionShuffleDescriptor(
815:                         consumedPartition,
816:                         TaskDeploymentDescriptorFactory.PartitionLocationConstraint.MUST_BE_KNOWN,
817:                         // because partition is already finished, false is fair enough.
818:                         false);
819:         return new PartitionInfo(intermediateDataSetID, shuffleDescriptor);
820:     }
