987:     void markFinished(Map<String, Accumulator<?, ?>> userAccumulators, IOMetrics metrics) {
988: 
989:         assertRunningInJobMasterMainThread();
990: 
991:         // this call usually comes during RUNNING, but may also come while still in deploying (very
992:         // fast tasks!)
993:         while (true) {
994:             ExecutionState current = this.state;
995: 
996:             if (current == INITIALIZING || current == RUNNING || current == DEPLOYING) {
997: 
998:                 if (transitionState(current, FINISHED)) {
999:                     try {
1000:                         finishPartitionsAndUpdateConsumers();
1001:                         updateAccumulatorsAndMetrics(userAccumulators, metrics);
1002:                         releaseAssignedResource(null);
1003:                         vertex.getExecutionGraphAccessor().deregisterExecution(this);
1004:                     } finally {
1005:                         vertex.executionFinished(this);
1006:                     }
1007:                     return;
1008:                 }
1009:             } else if (current == CANCELING) {
1010:                 // we sent a cancel call, and the task manager finished before it arrived. We
1011:                 // will never get a CANCELED call back from the job manager
1012:                 completeCancelling(userAccumulators, metrics, true);
1013:                 return;
1014:             } else if (current == CANCELED || current == FAILED) {
1015:                 if (LOG.isDebugEnabled()) {
1016:                     LOG.debug("Task FINISHED, but concurrently went to state " + state);
1017:                 }
1018:                 return;
1019:             } else {
1020:                 // this should not happen, we need to fail this
1021:                 markFailed(
1022:                         new Exception(
1023:                                 "Vertex received FINISHED message while being in state " + state));
1024:                 return;
1025:             }
1026:         }
1027:     }
