1047:     private boolean startCancelling(int numberCancelRetries) {
1048:         if (transitionState(state, CANCELING)) {
1049:             taskManagerLocationFuture.cancel(false);
1050:             sendCancelRpcCall(numberCancelRetries);
1051:             return true;
1052:         } else {
1053:             return false;
1054:         }
1055:     }
