1107:     private void finishCancellation(boolean releasePartitions) {
1108:         releaseAssignedResource(new FlinkException("Execution " + this + " was cancelled."));
1109:         vertex.getExecutionGraphAccessor().deregisterExecution(this);
1110:         handlePartitionCleanup(releasePartitions, releasePartitions);
1111:     }
