1252:     private boolean switchTo(ExecutionState from, ExecutionState to) {
1253: 
1254:         if (transitionState(from, to)) {
1255:             return true;
1256:         } else {
1257:             // something happened while the call was in progress.
1258:             // it can mean:
1259:             //  - canceling, while deployment was in progress. state is now canceling, or canceled,
1260:             // if the response overtook
1261:             //  - finishing (execution and finished call overtook the deployment answer, which is
1262:             // possible and happens for fast tasks)
1263:             //  - failed (execution, failure, and failure message overtook the deployment answer)
1264: 
1265:             ExecutionState currentState = this.state;
1266: 
1267:             if (currentState == FINISHED || currentState == CANCELED) {
1268:                 // do nothing, the task was really fast (nice)
1269:                 // or it was canceled really fast
1270:             } else if (currentState == CANCELING || currentState == FAILED) {
1271:                 if (LOG.isDebugEnabled()) {
1272:                     // this log statement is guarded because the 'getVertexWithAttempt()' method
1273:                     // performs string concatenations
1274:                     LOG.debug(
1275:                             "Concurrent canceling/failing of {} while deployment was in progress.",
1276:                             getVertexWithAttempt());
1277:                 }
1278:                 sendCancelRpcCall(NUM_CANCEL_CALL_TRIES);
1279:             } else {
1280:                 String message =
1281:                         String.format(
1282:                                 "Concurrent unexpected state transition of task %s from %s (expected %s) to %s while deployment was in progress.",
1283:                                 getAttemptId(), currentState, from, to);
1284: 
1285:                 LOG.debug(message);
1286: 
1287:                 // undo the deployment
1288:                 sendCancelRpcCall(NUM_CANCEL_CALL_TRIES);
1289: 
1290:                 // record the failure
1291:                 markFailed(new Exception(message));
1292:             }
1293: 
1294:             return false;
1295:         }
1296:     }
