1298:     /**
1299:      * This method sends a CancelTask message to the instance of the assigned slot.
1300:      *
1301:      * <p>The sending is tried up to NUM_CANCEL_CALL_TRIES times.
1302:      */
1303:     private void sendCancelRpcCall(int numberRetries) {
1304:         final LogicalSlot slot = assignedResource;
1305: 
1306:         if (slot != null) {
1307:             final TaskManagerGateway taskManagerGateway = slot.getTaskManagerGateway();
1308:             final ComponentMainThreadExecutor jobMasterMainThreadExecutor =
1309:                     getVertex().getExecutionGraphAccessor().getJobMasterMainThreadExecutor();
1310: 
1311:             CompletableFuture<Acknowledge> cancelResultFuture =
1312:                     FutureUtils.retry(
1313:                             () -> taskManagerGateway.cancelTask(attemptId, rpcTimeout),
1314:                             numberRetries,
1315:                             jobMasterMainThreadExecutor);
1316: 
1317:             cancelResultFuture.whenComplete(
1318:                     (ack, failure) -> {
1319:                         if (failure != null) {
1320:                             fail(new Exception("Task could not be canceled.", failure));
1321:                         }
1322:                     });
1323:         }
1324:     }
