1326:     private void startTrackingPartitions(
1327:             final ResourceID taskExecutorId,
1328:             final Collection<ResultPartitionDeploymentDescriptor> partitions) {
1329:         JobMasterPartitionTracker partitionTracker =
1330:                 vertex.getExecutionGraphAccessor().getPartitionTracker();
1331:         for (ResultPartitionDeploymentDescriptor partition : partitions) {
