1336:     void handlePartitionCleanup(
1337:             boolean releasePipelinedPartitions, boolean releaseBlockingPartitions) {
1338:         if (releasePipelinedPartitions) {
1339:             sendReleaseIntermediateResultPartitionsRpcCall();
1340:         }
1341: 
1342:         final Collection<ResultPartitionID> partitionIds = getPartitionIds();
1343:         final JobMasterPartitionTracker partitionTracker =
1344:                 getVertex().getExecutionGraphAccessor().getPartitionTracker();
1345: 
1346:         if (!partitionIds.isEmpty()) {
1347:             if (releaseBlockingPartitions) {
1348:                 LOG.info("Discarding the results produced by task execution {}.", attemptId);
1349:                 partitionTracker.stopTrackingAndReleasePartitions(partitionIds);
1350:             } else {
1351:                 partitionTracker.stopTrackingPartitions(partitionIds);
1352:             }
1353:         }
1354:     }
