1356:     private Collection<ResultPartitionID> getPartitionIds() {
1357:         return producedPartitions.values().stream()
1358:                 .map(ResultPartitionDeploymentDescriptor::getShuffleDescriptor)
1359:                 .map(ShuffleDescriptor::getResultPartitionID)
1360:                 .collect(Collectors.toList());
1361:     }
1362: 
1363:     private void sendReleaseIntermediateResultPartitionsRpcCall() {
1364:         LOG.info("Discarding the results produced by task execution {}.", attemptId);
1365:         final LogicalSlot slot = assignedResource;
1366: 
1367:         if (slot != null) {
1368:             final TaskManagerGateway taskManagerGateway = slot.getTaskManagerGateway();
1369: 
1370:             final ShuffleMaster<?> shuffleMaster =
1371:                     getVertex().getExecutionGraphAccessor().getShuffleMaster();
1372: 
1373:             Set<ResultPartitionID> partitionIds =
1374:                     producedPartitions.values().stream()
1375:                             .filter(
1376:                                     resultPartitionDeploymentDescriptor ->
1377:                                             resultPartitionDeploymentDescriptor
1378:                                                     .getPartitionType()
1379:                                                     .isReleaseByUpstream())
1380:                             .map(ResultPartitionDeploymentDescriptor::getShuffleDescriptor)
1381:                             .peek(shuffleMaster::releasePartitionExternally)
1382:                             .map(ShuffleDescriptor::getResultPartitionID)
1383:                             .collect(Collectors.toSet());
1384: 
1385:             if (!partitionIds.isEmpty()) {
1386:                 // TODO For some tests this could be a problem when querying too early if all
1387:                 // resources were released
1388:                 taskManagerGateway.releasePartitions(getVertex().getJobId(), partitionIds);
1389:             }
1390:         }
1391:     }
