1427:     /**
1428:      * Releases the assigned resource and completes the release future once the assigned resource
1429:      * has been successfully released.
1430:      *
1431:      * @param cause for the resource release, null if none
1432:      */
1433:     private void releaseAssignedResource(@Nullable Throwable cause) {
1434: 
1435:         assertRunningInJobMasterMainThread();
1436: 
1437:         final LogicalSlot slot = assignedResource;
1438: 
1439:         if (slot != null) {
1440:             ComponentMainThreadExecutor jobMasterMainThreadExecutor =
1441:                     getVertex().getExecutionGraphAccessor().getJobMasterMainThreadExecutor();
1442: 
1443:             slot.releaseSlot(cause)
1444:                     .whenComplete(
1445:                             (Object ignored, Throwable throwable) -> {
1446:                                 jobMasterMainThreadExecutor.assertRunningInMainThread();
1447:                                 if (throwable != null) {
1448:                                     releaseFuture.completeExceptionally(throwable);
1449:                                 } else {
1450:                                     releaseFuture.complete(null);
1451:                                 }
1452:                             });
1453:         } else {
1454:             // no assigned resource --> we can directly complete the release future
1455:             releaseFuture.complete(null);
1456:         }
1457:     }
