1471:     private boolean transitionState(
1472:             ExecutionState currentState, ExecutionState targetState, Throwable error) {
1473:         // sanity check
1474:         if (currentState.isTerminal()) {
1475:             throw new IllegalStateException(
1476:                     "Cannot leave terminal state "
1477:                             + currentState
1478:                             + " to transition to "
1479:                             + targetState
1480:                             + '.');
1481:         }
1482: 
1483:         if (state == currentState) {
1484:             state = targetState;
1485:             markTimestamp(currentState, targetState);
1486: 
1487:             if (error == null) {
1488:                 LOG.info(
1489:                         "{} ({}) switched from {} to {}.",
1490:                         getVertex().getTaskNameWithSubtaskIndex(),
1491:                         getAttemptId(),
1492:                         currentState,
1493:                         targetState);
1494:             } else if (LOG.isInfoEnabled()) {
1495:                 LOG.info(
1496:                         "{} ({}) switched from {} to {} on {}.",
1497:                         getVertex().getTaskNameWithSubtaskIndex(),
1498:                         getAttemptId(),
1499:                         currentState,
1500:                         targetState,
1501:                         getLocationInformation(),
1502:                         ExceptionUtils.stripCompletionException(error));
1503:             }
1504: 
1505:             if (targetState == INITIALIZING || targetState == RUNNING) {
1506:                 initializingOrRunningFuture.complete(null);
1507:             } else if (targetState.isTerminal()) {
1508:                 // complete the terminal state future
1509:                 terminalStateFuture.complete(targetState);
1510:             }
1511: 
1512:             // make sure that the state transition completes normally.
1513:             // potential errors (in listeners may not affect the main logic)
1514:             try {
1515:                 vertex.notifyStateTransition(this, currentState, targetState);
1516:             } catch (Throwable t) {
1517:                 LOG.error(
1518:                         "Error while notifying execution graph of execution state transition.", t);
1519:             }
1520:             return true;
1521:         } else {
1522:             return false;
1523:         }
1524:     }
