580:     /**
581:      * Creates the parallelism store for a set of vertices, optionally with a flag to leave the
582:      * vertex parallelism unchanged. If the flag is set, the parallelisms must be valid for
583:      * execution.
584:      *
585:      * <p>We need to set parallelism to the max possible value when requesting resources, but when
586:      * executing the graph we should respect what we are actually given.
587:      *
588:      * @param vertices The vertices to store parallelism information for
589:      * @param adjustParallelism Whether to adjust the parallelism
590:      * @param defaultMaxParallelismFunc a function for computing a default max parallelism if none
591:      *     is specified on a given vertex
592:      * @return The parallelism store.
593:      */
594:     @VisibleForTesting
595:     static VertexParallelismStore computeReactiveModeVertexParallelismStore(
596:             Iterable<JobVertex> vertices,
597:             Function<JobVertex, Integer> defaultMaxParallelismFunc,
598:             boolean adjustParallelism) {
599:         DefaultVertexParallelismStore store = new DefaultVertexParallelismStore();
600: 
601:         for (JobVertex vertex : vertices) {
602:             // if no max parallelism was configured by the user, we calculate and set a default
603:             final int maxParallelism =
604:                     vertex.getMaxParallelism() == JobVertex.MAX_PARALLELISM_DEFAULT
605:                             ? defaultMaxParallelismFunc.apply(vertex)
606:                             : vertex.getMaxParallelism();
607:             // If the parallelism has already been adjusted, respect what has been configured in the
608:             // vertex. Otherwise, scale it to the max parallelism to attempt to be "as parallel as
609:             // possible"
610:             final int parallelism;
611:             if (adjustParallelism) {
612:                 parallelism = maxParallelism;
613:             } else {
614:                 parallelism = vertex.getParallelism();
615:             }
616: 
617:             VertexParallelismInformation parallelismInfo =
618:                     new DefaultVertexParallelismInfo(
619:                             parallelism,
620:                             maxParallelism,
621:                             // Allow rescaling if the new desired max parallelism
622:                             // is not less than what was declared here during scheduling.
623:                             // This prevents the situation where more resources are requested
624:                             // based on the computed default, when actually fewer are necessary.
625:                             (newMax) ->
626:                                     newMax >= maxParallelism
627:                                             ? Optional.empty()
628:                                             : Optional.of(
629:                                                     "Cannot lower max parallelism in Reactive mode."));
630:             store.setParallelismInfo(vertex.getID(), parallelismInfo);
631:         }
632: 
633:         return store;
634:     }
