136:     // Need to be in consistent with that VectorizedPrimitiveColumnReader#readBatchHelper
137:     // TODO Reduce the duplicated code
138:     private Object readPrimitiveTypedRow(LogicalType category) {
139:         switch (category.getTypeRoot()) {
140:             case CHAR:
141:             case VARCHAR:
142:             case BINARY:
143:             case VARBINARY:
144:                 return dataColumn.readBytes();
145:             case BOOLEAN:
146:                 return dataColumn.readBoolean();
147:             case TIME_WITHOUT_TIME_ZONE:
148:             case DATE:
149:             case INTEGER:
150:                 return dataColumn.readInteger();
151:             case TINYINT:
152:                 return dataColumn.readTinyInt();
153:             case SMALLINT:
154:                 return dataColumn.readSmallInt();
155:             case BIGINT:
156:                 return dataColumn.readLong();
157:             case FLOAT:
158:                 return dataColumn.readFloat();
159:             case DOUBLE:
160:                 return dataColumn.readDouble();
161:             case DECIMAL:
162:                 switch (descriptor.getPrimitiveType().getPrimitiveTypeName()) {
163:                     case INT32:
164:                         return dataColumn.readInteger();
165:                     case INT64:
166:                         return dataColumn.readLong();
167:                     case BINARY:
168:                     case FIXED_LEN_BYTE_ARRAY:
169:                         return dataColumn.readBytes();
170:                 }
171:             case TIMESTAMP_WITHOUT_TIME_ZONE:
172:             case TIMESTAMP_WITH_LOCAL_TIME_ZONE:
173:                 return dataColumn.readTimestamp();
174:             default:
175:                 throw new RuntimeException("Unsupported type in the list: " + category);
176:         }
177:     }
