91: /** Util for generating {@link ParquetColumnarRowSplitReader}. */
92: public class ParquetSplitReaderUtil {
93: 
94:     /** Util for generating partitioned {@link ParquetColumnarRowSplitReader}. */
95:     public static ParquetColumnarRowSplitReader genPartColumnarRowReader(
96:             boolean utcTimestamp,
97:             boolean caseSensitive,
98:             Configuration conf,
99:             String[] fullFieldNames,
100:             DataType[] fullFieldTypes,
101:             Map<String, Object> partitionSpec,
102:             int[] selectedFields,
103:             int batchSize,
104:             Path path,
105:             long splitStart,
106:             long splitLength)
107:             throws IOException {
108:         List<String> nonPartNames =
109:                 Arrays.stream(fullFieldNames)
110:                         .filter(n -> !partitionSpec.containsKey(n))
111:                         .collect(Collectors.toList());
112: 
113:         List<String> selNonPartNames =
114:                 Arrays.stream(selectedFields)
115:                         .mapToObj(i -> fullFieldNames[i])
116:                         .filter(nonPartNames::contains)
117:                         .collect(Collectors.toList());
118: 
119:         int[] selParquetFields = selNonPartNames.stream().mapToInt(nonPartNames::indexOf).toArray();
120: 
121:         ParquetColumnarRowSplitReader.ColumnBatchGenerator gen =
122:                 readVectors -> {
123:                     // create and initialize the row batch
124:                     ColumnVector[] vectors = new ColumnVector[selectedFields.length];
125:                     for (int i = 0; i < vectors.length; i++) {
126:                         String name = fullFieldNames[selectedFields[i]];
127:                         LogicalType type = fullFieldTypes[selectedFields[i]].getLogicalType();
128:                         vectors[i] =
129:                                 partitionSpec.containsKey(name)
130:                                         ? createVectorFromConstant(
131:                                                 type, partitionSpec.get(name), batchSize)
132:                                         : readVectors[selNonPartNames.indexOf(name)];
133:                     }
134:                     return new VectorizedColumnBatch(vectors);
135:                 };
136: 
137:         return new ParquetColumnarRowSplitReader(
138:                 utcTimestamp,
139:                 caseSensitive,
140:                 conf,
141:                 Arrays.stream(selParquetFields)
142:                         .mapToObj(i -> fullFieldTypes[i].getLogicalType())
143:                         .toArray(LogicalType[]::new),
144:                 selNonPartNames.toArray(new String[0]),
145:                 gen,
146:                 batchSize,
147:                 new org.apache.hadoop.fs.Path(path.toUri()),
148:                 splitStart,
149:                 splitLength);
150:     }
