152:     public static ColumnVector createVectorFromConstant(
153:             LogicalType category, Object value, int batchSize) {
154:         switch (category.getTypeRoot()) {
155:             case CHAR:
156:             case VARCHAR:
157:             case BINARY:
158:             case VARBINARY:
159:                 HeapBytesVector bsv = new HeapBytesVector(batchSize);
160:                 if (value == null) {
161:                     bsv.fillWithNulls();
162:                 } else {
163:                     bsv.fill(
164:                             value instanceof byte[]
165:                                     ? (byte[]) value
166:                                     : value.toString().getBytes(StandardCharsets.UTF_8));
167:                 }
168:                 return bsv;
169:             case BOOLEAN:
170:                 HeapBooleanVector bv = new HeapBooleanVector(batchSize);
171:                 if (value == null) {
172:                     bv.fillWithNulls();
173:                 } else {
174:                     bv.fill((boolean) value);
175:                 }
176:                 return bv;
177:             case TINYINT:
178:                 HeapByteVector byteVector = new HeapByteVector(batchSize);
179:                 if (value == null) {
180:                     byteVector.fillWithNulls();
181:                 } else {
182:                     byteVector.fill(((Number) value).byteValue());
183:                 }
184:                 return byteVector;
185:             case SMALLINT:
186:                 HeapShortVector sv = new HeapShortVector(batchSize);
187:                 if (value == null) {
188:                     sv.fillWithNulls();
189:                 } else {
190:                     sv.fill(((Number) value).shortValue());
191:                 }
192:                 return sv;
193:             case INTEGER:
194:                 HeapIntVector iv = new HeapIntVector(batchSize);
195:                 if (value == null) {
196:                     iv.fillWithNulls();
197:                 } else {
198:                     iv.fill(((Number) value).intValue());
199:                 }
200:                 return iv;
201:             case BIGINT:
202:                 HeapLongVector lv = new HeapLongVector(batchSize);
203:                 if (value == null) {
204:                     lv.fillWithNulls();
205:                 } else {
206:                     lv.fill(((Number) value).longValue());
207:                 }
208:                 return lv;
209:             case DECIMAL:
210:                 DecimalType decimalType = (DecimalType) category;
211:                 int precision = decimalType.getPrecision();
212:                 int scale = decimalType.getScale();
213:                 DecimalData decimal =
214:                         value == null
215:                                 ? null
216:                                 : Preconditions.checkNotNull(
217:                                         DecimalData.fromBigDecimal(
218:                                                 (BigDecimal) value, precision, scale));
219:                 ColumnVector internalVector;
220:                 if (ParquetSchemaConverter.is32BitDecimal(precision)) {
221:                     internalVector =
222:                             createVectorFromConstant(
223:                                     new IntType(),
224:                                     decimal == null ? null : (int) decimal.toUnscaledLong(),
225:                                     batchSize);
226:                 } else if (ParquetSchemaConverter.is64BitDecimal(precision)) {
227:                     internalVector =
228:                             createVectorFromConstant(
229:                                     new BigIntType(),
230:                                     decimal == null ? null : decimal.toUnscaledLong(),
231:                                     batchSize);
232:                 } else {
233:                     internalVector =
234:                             createVectorFromConstant(
235:                                     new VarBinaryType(),
236:                                     decimal == null ? null : decimal.toUnscaledBytes(),
237:                                     batchSize);
238:                 }
239:                 return new ParquetDecimalVector(internalVector);
240:             case FLOAT:
241:                 HeapFloatVector fv = new HeapFloatVector(batchSize);
242:                 if (value == null) {
243:                     fv.fillWithNulls();
244:                 } else {
245:                     fv.fill(((Number) value).floatValue());
246:                 }
247:                 return fv;
248:             case DOUBLE:
249:                 HeapDoubleVector dv = new HeapDoubleVector(batchSize);
250:                 if (value == null) {
251:                     dv.fillWithNulls();
252:                 } else {
253:                     dv.fill(((Number) value).doubleValue());
254:                 }
255:                 return dv;
256:             case DATE:
257:                 if (value instanceof LocalDate) {
258:                     value = Date.valueOf((LocalDate) value);
259:                 }
260:                 return createVectorFromConstant(
261:                         new IntType(), value == null ? null : toInternal((Date) value), batchSize);
262:             case TIMESTAMP_WITHOUT_TIME_ZONE:
263:                 HeapTimestampVector tv = new HeapTimestampVector(batchSize);
264:                 if (value == null) {
265:                     tv.fillWithNulls();
266:                 } else {
267:                     tv.fill(TimestampData.fromLocalDateTime((LocalDateTime) value));
268:                 }
269:                 return tv;
270:             default:
271:                 throw new UnsupportedOperationException("Unsupported type: " + category);
272:         }
273:     }
