106:     /**
107:      * Perform chaining optimization. It will iterate the transformations defined in the given
108:      * StreamExecutionEnvironment and update them with the chained transformations.
109:      */
110:     @SuppressWarnings("unchecked")
111:     public static void apply(StreamExecutionEnvironment env) throws Exception {
112:         if (env.getConfiguration().get(PythonOptions.PYTHON_OPERATOR_CHAINING_ENABLED)) {
113:             final Field transformationsField =
114:                     StreamExecutionEnvironment.class.getDeclaredField("transformations");
115:             transformationsField.setAccessible(true);
116:             final List<Transformation<?>> transformations =
117:                     (List<Transformation<?>>) transformationsField.get(env);
118:             transformationsField.set(env, optimize(transformations));
119:         }
120:     }
121: 
122:     /**
123:      * Perform chaining optimization. It will iterate the transformations defined in the given
124:      * StreamExecutionEnvironment and update them with the chained transformations. Besides, it will
125:      * return the transformation after chaining optimization for the given transformation.
126:      */
127:     @SuppressWarnings("unchecked")
128:     public static Transformation<?> apply(
129:             StreamExecutionEnvironment env, Transformation<?> transformation) throws Exception {
130:         if (env.getConfiguration().get(PythonOptions.PYTHON_OPERATOR_CHAINING_ENABLED)) {
131:             final Field transformationsField =
132:                     StreamExecutionEnvironment.class.getDeclaredField("transformations");
133:             transformationsField.setAccessible(true);
134:             final List<Transformation<?>> transformations =
135:                     (List<Transformation<?>>) transformationsField.get(env);
136:             final Tuple2<List<Transformation<?>>, Transformation<?>> resultTuple =
137:                     optimize(transformations, transformation);
138:             transformationsField.set(env, resultTuple.f0);
139:             return resultTuple.f1;
140:         } else {
141:             return transformation;
142:         }
143:     }
