178:     public static Tuple2<List<Transformation<?>>, Transformation<?>> optimize(
179:             List<Transformation<?>> transformations, Transformation<?> targetTransformation) {
180:         final Map<Transformation<?>, Set<Transformation<?>>> outputMap =
181:                 buildOutputMap(transformations);
182: 
183:         final LinkedHashSet<Transformation<?>> chainedTransformations = new LinkedHashSet<>();
184:         final Set<Transformation<?>> alreadyTransformed = Sets.newIdentityHashSet();
185:         final Queue<Transformation<?>> toTransformQueue = Queues.newArrayDeque();
186:         toTransformQueue.add(targetTransformation);
187:         while (!toTransformQueue.isEmpty()) {
188:             final Transformation<?> toTransform = toTransformQueue.poll();
189:             if (!alreadyTransformed.contains(toTransform)) {
190:                 alreadyTransformed.add(toTransform);
191: 
192:                 final ChainInfo chainInfo = chainWithInputIfPossible(toTransform, outputMap);
193:                 chainedTransformations.add(chainInfo.newTransformation);
194:                 chainedTransformations.removeAll(chainInfo.oldTransformations);
195:                 alreadyTransformed.addAll(chainInfo.oldTransformations);
196: 
197:                 // Add the chained transformation and its inputs to the to-optimize list
198:                 toTransformQueue.add(chainInfo.newTransformation);
199:                 toTransformQueue.addAll(chainInfo.newTransformation.getInputs());
200: 
201:                 if (toTransform == targetTransformation) {
202:                     targetTransformation = chainInfo.newTransformation;
203:                 }
204:             }
