211:      * transformation.
212:      */
213:     private static Map<Transformation<?>, Set<Transformation<?>>> buildOutputMap(
214:             List<Transformation<?>> transformations) {
215:         final Map<Transformation<?>, Set<Transformation<?>>> outputMap = new HashMap<>();
216:         final Queue<Transformation<?>> toTransformQueue = Queues.newArrayDeque(transformations);
217:         final Set<Transformation<?>> alreadyTransformed = Sets.newIdentityHashSet();
218:         while (!toTransformQueue.isEmpty()) {
219:             Transformation<?> transformation = toTransformQueue.poll();
220:             if (!alreadyTransformed.contains(transformation)) {
221:                 alreadyTransformed.add(transformation);
222:                 for (Transformation<?> input : transformation.getInputs()) {
223:                     Set<Transformation<?>> outputs =
224:                             outputMap.computeIfAbsent(input, i -> Sets.newHashSet());
225:                     outputs.add(transformation);
226:                 }
227:                 toTransformQueue.addAll(transformation.getInputs());
228:             }
229:         }
230:         return outputMap;
231:     }
