270:     @SuppressWarnings("unchecked")
271:     private static Transformation<?> createChainedTransformation(
272:             Transformation<?> upTransform, Transformation<?> downTransform) {
273:         DataStreamPythonFunctionOperator<?> upOperator =
274:                 (DataStreamPythonFunctionOperator<?>)
275:                         ((SimpleOperatorFactory<?>) getOperatorFactory(upTransform)).getOperator();
276: 
277:         DataStreamPythonFunctionOperator<?> downOperator =
278:                 (DataStreamPythonFunctionOperator<?>)
279:                         ((SimpleOperatorFactory<?>) getOperatorFactory(downTransform))
280:                                 .getOperator();
281: 
282:         assert arePythonOperatorsInSameExecutionEnvironment(upOperator, downOperator);
283: 
284:         final DataStreamPythonFunctionInfo upPythonFunctionInfo =
285:                 upOperator.getPythonFunctionInfo().copy();
286: 
287:         final DataStreamPythonFunctionInfo downPythonFunctionInfo =
288:                 downOperator.getPythonFunctionInfo().copy();
289: 
290:         DataStreamPythonFunctionInfo headPythonFunctionInfoOfDownOperator = downPythonFunctionInfo;
291:         while (headPythonFunctionInfoOfDownOperator.getInputs().length != 0) {
292:             headPythonFunctionInfoOfDownOperator =
293:                     (DataStreamPythonFunctionInfo)
294:                             headPythonFunctionInfoOfDownOperator.getInputs()[0];
295:         }
296:         headPythonFunctionInfoOfDownOperator.setInputs(
297:                 new DataStreamPythonFunctionInfo[] {upPythonFunctionInfo});
298: 
299:         final DataStreamPythonFunctionOperator chainedOperator =
300:                 upOperator.copy(
301:                         downPythonFunctionInfo,
302:                         ((DataStreamPythonFunctionOperator) downOperator).getProducedType());
303:         chainedOperator.addSideOutputTags(downOperator.getSideOutputTags());
304: 
305:         PhysicalTransformation<?> chainedTransformation;
306:         if (upOperator instanceof OneInputStreamOperator) {
307:             chainedTransformation =
308:                     new OneInputTransformation(
309:                             upTransform.getInputs().get(0),
310:                             upTransform.getName() + ", " + downTransform.getName(),
311:                             (OneInputStreamOperator<?, ?>) chainedOperator,
312:                             downTransform.getOutputType(),
313:                             upTransform.getParallelism(),
314:                             false);
315: 
316:             ((OneInputTransformation<?, ?>) chainedTransformation)
317:                     .setStateKeySelector(
318:                             ((OneInputTransformation) upTransform).getStateKeySelector());
319:             ((OneInputTransformation<?, ?>) chainedTransformation)
320:                     .setStateKeyType(
321:                             ((OneInputTransformation<?, ?>) upTransform).getStateKeyType());
322:         } else {
323:             chainedTransformation =
324:                     new TwoInputTransformation(
325:                             upTransform.getInputs().get(0),
326:                             upTransform.getInputs().get(1),
327:                             upTransform.getName() + ", " + downTransform.getName(),
328:                             (TwoInputStreamOperator<?, ?, ?>) chainedOperator,
329:                             downTransform.getOutputType(),
330:                             upTransform.getParallelism(),
331:                             false);
332: 
333:             ((TwoInputTransformation<?, ?, ?>) chainedTransformation)
334:                     .setStateKeySelectors(
335:                             ((TwoInputTransformation) upTransform).getStateKeySelector1(),
336:                             ((TwoInputTransformation) upTransform).getStateKeySelector2());
337:             ((TwoInputTransformation<?, ?, ?>) chainedTransformation)
338:                     .setStateKeyType(
339:                             ((TwoInputTransformation<?, ?, ?>) upTransform).getStateKeyType());
340:         }
341: 
342:         chainedTransformation.setUid(upTransform.getUid());
343:         if (upTransform.getUserProvidedNodeHash() != null) {
344:             chainedTransformation.setUidHash(upTransform.getUserProvidedNodeHash());
345:         }
346: 
347:         for (ManagedMemoryUseCase useCase : upTransform.getManagedMemorySlotScopeUseCases()) {
348:             chainedTransformation.declareManagedMemoryUseCaseAtSlotScope(useCase);
349:         }
350:         for (ManagedMemoryUseCase useCase : downTransform.getManagedMemorySlotScopeUseCases()) {
351:             chainedTransformation.declareManagedMemoryUseCaseAtSlotScope(useCase);
352:         }
353: 
354:         for (Map.Entry<ManagedMemoryUseCase, Integer> useCase :
355:                 upTransform.getManagedMemoryOperatorScopeUseCaseWeights().entrySet()) {
356:             chainedTransformation.declareManagedMemoryUseCaseAtOperatorScope(
357:                     useCase.getKey(), useCase.getValue());
358:         }
359:         for (Map.Entry<ManagedMemoryUseCase, Integer> useCase :
360:                 downTransform.getManagedMemoryOperatorScopeUseCaseWeights().entrySet()) {
361:             chainedTransformation.declareManagedMemoryUseCaseAtOperatorScope(
362:                     useCase.getKey(),
363:                     useCase.getValue()
364:                             + chainedTransformation
365:                                     .getManagedMemoryOperatorScopeUseCaseWeights()
366:                                     .getOrDefault(useCase.getKey(), 0));
367:         }
368: 
369:         chainedTransformation.setBufferTimeout(
370:                 Math.min(upTransform.getBufferTimeout(), downTransform.getBufferTimeout()));
371: 
372:         if (upTransform.getMaxParallelism() > 0) {
373:             chainedTransformation.setMaxParallelism(upTransform.getMaxParallelism());
374:         }
375:         chainedTransformation.setChainingStrategy(
376:                 getOperatorFactory(upTransform).getChainingStrategy());
377:         chainedTransformation.setCoLocationGroupKey(upTransform.getCoLocationGroupKey());
378:         chainedTransformation.setResources(
379:                 upTransform.getMinResources().merge(downTransform.getMinResources()),
380:                 upTransform.getPreferredResources().merge(downTransform.getPreferredResources()));
381: 
382:         if (upTransform.getSlotSharingGroup().isPresent()) {
383:             chainedTransformation.setSlotSharingGroup(upTransform.getSlotSharingGroup().get());
384:         }
385: 
386:         if (upTransform.getDescription() != null && downTransform.getDescription() != null) {
387:             chainedTransformation.setDescription(
388:                     upTransform.getDescription() + ", " + downTransform.getDescription());
389:         } else if (upTransform.getDescription() != null) {
390:             chainedTransformation.setDescription(upTransform.getDescription());
391:         } else if (downTransform.getDescription() != null) {
392:             chainedTransformation.setDescription(downTransform.getDescription());
393:         }
394:         return chainedTransformation;
395:     }
