397:     private static boolean isChainable(
398:             Transformation<?> upTransform,
399:             Transformation<?> downTransform,
400:             Map<Transformation<?>, Set<Transformation<?>>> outputMap) {
401:         return upTransform.getParallelism() == downTransform.getParallelism()
402:                 && upTransform.getMaxParallelism() == downTransform.getMaxParallelism()
403:                 && upTransform.getSlotSharingGroup().equals(downTransform.getSlotSharingGroup())
404:                 && areOperatorsChainable(upTransform, downTransform)
405:                 && outputMap.get(upTransform).size() == 1;
406:     }
407: 
408:     private static boolean areOperatorsChainable(
409:             Transformation<?> upTransform, Transformation<?> downTransform) {
410:         if (!areOperatorsChainableByChainingStrategy(upTransform, downTransform)) {
411:             return false;
412:         }
413: 
414:         if (upTransform instanceof PythonBroadcastStateTransformation
415:                 || upTransform instanceof PythonKeyedBroadcastStateTransformation) {
416:             return false;
417:         }
418: 
419:         DataStreamPythonFunctionOperator<?> upOperator =
420:                 (DataStreamPythonFunctionOperator<?>)
421:                         ((SimpleOperatorFactory<?>) getOperatorFactory(upTransform)).getOperator();
422: 
423:         DataStreamPythonFunctionOperator<?> downOperator =
424:                 (DataStreamPythonFunctionOperator<?>)
425:                         ((SimpleOperatorFactory<?>) getOperatorFactory(downTransform))
426:                                 .getOperator();
427: 
428:         if (!arePythonOperatorsInSameExecutionEnvironment(upOperator, downOperator)) {
429:             return false;
430:         }
431: 
432:         return (downOperator instanceof ExternalPythonProcessOperator
433:                         && (upOperator instanceof ExternalPythonKeyedProcessOperator
434:                                 || upOperator instanceof ExternalPythonKeyedCoProcessOperator
435:                                 || upOperator instanceof ExternalPythonProcessOperator
436:                                 || upOperator instanceof ExternalPythonCoProcessOperator))
437:                 || (downOperator instanceof EmbeddedPythonProcessOperator
438:                         && (upOperator instanceof EmbeddedPythonKeyedProcessOperator
439:                                 || upOperator instanceof EmbeddedPythonKeyedCoProcessOperator
440:                                 || upOperator instanceof EmbeddedPythonProcessOperator
441:                                 || upOperator instanceof EmbeddedPythonCoProcessOperator
442:                                 || upOperator instanceof EmbeddedPythonWindowOperator));
443:     }
444: 
445:     private static boolean arePythonOperatorsInSameExecutionEnvironment(
446:             DataStreamPythonFunctionOperator<?> upOperator,
447:             DataStreamPythonFunctionOperator<?> downOperator) {
448:         return upOperator instanceof AbstractExternalDataStreamPythonFunctionOperator
449:                         && downOperator instanceof AbstractExternalDataStreamPythonFunctionOperator
450:                 || upOperator instanceof AbstractEmbeddedDataStreamPythonFunctionOperator
451:                         && downOperator instanceof AbstractEmbeddedDataStreamPythonFunctionOperator;
452:     }
453: 
454:     private static boolean areOperatorsChainableByChainingStrategy(
455:             Transformation<?> upTransform, Transformation<?> downTransform) {
456:         // we use switch/case here to make sure this is exhaustive if ever values are added to the
457:         // ChainingStrategy enum
458:         boolean isChainable;
459: 
460:         StreamOperatorFactory<?> upStreamOperator = getOperatorFactory(upTransform);
461:         StreamOperatorFactory<?> downStreamOperator = getOperatorFactory(downTransform);
462: 
463:         switch (upStreamOperator.getChainingStrategy()) {
464:             case NEVER:
465:                 isChainable = false;
466:                 break;
467:             case ALWAYS:
468:             case HEAD:
469:             case HEAD_WITH_SOURCES:
470:                 isChainable = true;
471:                 break;
472:             default:
473:                 throw new RuntimeException(
474:                         "Unknown chaining strategy: " + upStreamOperator.getChainingStrategy());
475:         }
476: 
477:         switch (downStreamOperator.getChainingStrategy()) {
478:             case NEVER:
479:             case HEAD:
480:                 isChainable = false;
481:                 break;
482:             case ALWAYS:
483:                 // keep the value from upstream
484:                 break;
485:             case HEAD_WITH_SOURCES:
486:                 // only if upstream is a source
487:                 isChainable &= (upStreamOperator instanceof SourceOperatorFactory);
488:                 break;
489:             default:
490:                 throw new RuntimeException(
491:                         "Unknown chaining strategy: " + upStreamOperator.getChainingStrategy());
492:         }
493: 
494:         return isChainable;
495:     }
