497:     // ----------------------- Utility Methods -----------------------
498: 
499:     private static void replaceInput(
500:             Transformation<?> transformation,
501:             Transformation<?> oldInput,
502:             Transformation<?> newInput) {
503:         try {
504:             if (transformation instanceof OneInputTransformation
505:                     || transformation instanceof FeedbackTransformation
506:                     || transformation instanceof SideOutputTransformation
507:                     || transformation instanceof ReduceTransformation
508:                     || transformation instanceof LegacySinkTransformation
509:                     || transformation instanceof TimestampsAndWatermarksTransformation
510:                     || transformation instanceof PartitionTransformation) {
511:                 final Field inputField = transformation.getClass().getDeclaredField("input");
512:                 inputField.setAccessible(true);
513:                 inputField.set(transformation, newInput);
514:             } else if (transformation instanceof SinkTransformation) {
515:                 final Field inputField = transformation.getClass().getDeclaredField("input");
516:                 inputField.setAccessible(true);
517:                 inputField.set(transformation, newInput);
518: 
519:                 final Field transformationField =
520:                         DataStream.class.getDeclaredField("transformation");
521:                 transformationField.setAccessible(true);
522:                 transformationField.set(
523:                         ((SinkTransformation<?, ?>) transformation).getInputStream(), newInput);
524:             } else if (transformation instanceof TwoInputTransformation) {
525:                 final Field inputField;
526:                 if (((TwoInputTransformation<?, ?, ?>) transformation).getInput1() == oldInput) {
527:                     inputField = transformation.getClass().getDeclaredField("input1");
528:                 } else {
529:                     inputField = transformation.getClass().getDeclaredField("input2");
530:                 }
531:                 inputField.setAccessible(true);
532:                 inputField.set(transformation, newInput);
533:             } else if (transformation instanceof UnionTransformation
534:                     || transformation instanceof AbstractMultipleInputTransformation) {
535:                 final Field inputsField = transformation.getClass().getDeclaredField("inputs");
536:                 inputsField.setAccessible(true);
537:                 List<Transformation<?>> newInputs = Lists.newArrayList();
538:                 newInputs.addAll(transformation.getInputs());
539:                 newInputs.remove(oldInput);
540:                 newInputs.add(newInput);
541:                 inputsField.set(transformation, newInputs);
542:             } else if (transformation instanceof AbstractBroadcastStateTransformation) {
543:                 final Field inputField;
544:                 if (((AbstractBroadcastStateTransformation<?, ?, ?>) transformation)
545:                                 .getRegularInput()
546:                         == oldInput) {
547:                     inputField = transformation.getClass().getDeclaredField("regularInput");
548:                 } else {
549:                     inputField = transformation.getClass().getDeclaredField("broadcastInput");
550:                 }
551:                 inputField.setAccessible(true);
552:                 inputField.set(transformation, newInput);
553:             } else {
554:                 throw new RuntimeException("Unsupported transformation: " + transformation);
555:             }
556:         } catch (NoSuchFieldException | IllegalAccessException e) {
557:             // This should never happen
558:             throw new RuntimeException(e);
559:         }
560:     }
561: 
562:     // ----------------------- Utility Classes -----------------------
563: 
564:     private static class ChainInfo {
565:         /** The transformation which represents the chaining of the {@link #oldTransformations}. */
566:         public final Transformation<?> newTransformation;
567: 
568:         /** The transformations which will be chained together. */
569:         public final Collection<Transformation<?>> oldTransformations;
570: 
571:         private ChainInfo(
572:                 Transformation<?> newTransformation,
573:                 Collection<Transformation<?>> oldTransformations) {
574:             this.newTransformation = newTransformation;
575:             this.oldTransformations = oldTransformations;
576:         }
577: 
578:         /** No chaining happens. */
579:         public static ChainInfo of(Transformation<?> newTransformation) {
580:             return new ChainInfo(newTransformation, Collections.emptyList());
581:         }
582: 
583:         public static ChainInfo of(
584:                 Transformation<?> newTransformation,
585:                 Collection<Transformation<?>> oldTransformations) {
586:             return new ChainInfo(newTransformation, oldTransformations);
587:         }
588:     }
589: }
