45:  *
46:  * <p>Temporary file directory contains the following directory parts: 1.temporary base path
47:  * directory. 2.task id directory. 3.directories to specify partitioning. 4.data files. eg:
48:  * /tmp/task-0-attempt-0/p0=1/p1=2/fileName.
49:  */
50: @Internal
51: public class PartitionTempFileManager {
52:     private static final Logger LOG = LoggerFactory.getLogger(PartitionTempFileManager.class);
53: 
54:     private static final String TASK_DIR_PREFIX = "task-";
55:     private static final String ATTEMPT_PREFIX = "attempt-";
56: 
57:     /** <b>ATTENTION:</b> please keep TASK_DIR_FORMAT matching with TASK_DIR_PATTERN. */
58:     private static final String TASK_DIR_FORMAT = "%s%d-%s%d";
59: 
60:     private static final Pattern TASK_DIR_PATTERN =
61:             Pattern.compile(TASK_DIR_PREFIX + "(\\d+)-" + ATTEMPT_PREFIX + "(\\d+)");
62:     private final int taskNumber;
63:     private final Path taskTmpDir;
64:     private final OutputFileConfig outputFileConfig;
65: 
66:     private transient int nameCounter = 0;
67: 
68:     public PartitionTempFileManager(
69:             FileSystemFactory factory, Path tmpPath, int taskNumber, int attemptNumber)
70:             throws IOException {
71:         this(factory, tmpPath, taskNumber, attemptNumber, new OutputFileConfig("", ""));
72:     }
73: 
74:     public PartitionTempFileManager(
75:             FileSystemFactory factory,
76:             Path tmpPath,
77:             int taskNumber,
78:             int attemptNumber,
79:             OutputFileConfig outputFileConfig)
80:             throws IOException {
81:         this.taskNumber = taskNumber;
82:         this.outputFileConfig = outputFileConfig;
83: 
84:         // generate task temp dir with task and attempt number like "task-0-attempt-0"
85:         String taskTmpDirName =
86:                 String.format(
87:                         TASK_DIR_FORMAT,
88:                         TASK_DIR_PREFIX,
89:                         taskNumber,
90:                         ATTEMPT_PREFIX,
91:                         attemptNumber);
92:         this.taskTmpDir = new Path(tmpPath, taskTmpDirName);
93:         factory.create(taskTmpDir.toUri()).delete(taskTmpDir, true);
94:     }
95: 
96:     /** Generate a new partition directory with partitions. */
97:     public Path createPartitionDir(String... partitions) {
98:         Path parentPath = taskTmpDir;
99:         for (String dir : partitions) {
100:             parentPath = new Path(parentPath, dir);
101:         }
102:         return new Path(parentPath, newFileName());
103:     }
104: 
105:     private String newFileName() {
106:         return String.format(
107:                 "%s-%s-file-%d%s",
108:                 outputFileConfig.getPartPrefix(),
109:                 taskName(taskNumber),
110:                 nameCounter++,
111:                 outputFileConfig.getPartSuffix());
112:     }
