144:     /** Collect all partitioned paths, aggregate according to partition spec. */
145:     public static Map<LinkedHashMap<String, String>, List<Path>> collectPartSpecToPaths(
146:             FileSystem fs, List<Path> taskPaths, int partColSize) {
147:         Map<LinkedHashMap<String, String>, List<Path>> specToPaths = new HashMap<>();
148:         for (Path taskPath : taskPaths) {
149:             searchPartSpecAndPaths(fs, taskPath, partColSize)
150:                     .forEach(
151:                             tuple2 ->
152:                                     specToPaths.compute(
153:                                             tuple2.f0,
154:                                             (spec, paths) -> {
155:                                                 paths = paths == null ? new ArrayList<>() : paths;
156:                                                 paths.add(tuple2.f1);
157:                                                 return paths;
158:                                             }));
159:         }
160:         return specToPaths;
161:     }
