119:     public static List<Path> listTaskTemporaryPaths(
120:             FileSystem fs, Path basePath, BiPredicate<Integer, Integer> taskAttemptFilter)
121:             throws Exception {
122:         List<Path> taskTmpPaths = new ArrayList<>();
123: 
124:         if (fs.exists(basePath)) {
125:             for (FileStatus taskStatus : fs.listStatus(basePath)) {
126:                 final String taskDirName = taskStatus.getPath().getName();
127:                 final Matcher matcher = TASK_DIR_PATTERN.matcher(taskDirName);
128:                 if (matcher.matches()) {
129:                     final int subtaskIndex = Integer.parseInt(matcher.group(1));
130:                     final int attemptNumber = Integer.parseInt(matcher.group(2));
131:                     if (taskAttemptFilter.test(subtaskIndex, attemptNumber)) {
132:                         taskTmpPaths.add(taskStatus.getPath());
133:                     }
134:                 }
135:             }
136:         } else {
137:             LOG.warn(
138:                     "The path {} doesn't exist. Maybe no data is generated in the path and the path is not created.",
139:                     basePath);
140:         }
141:         return taskTmpPaths;
