751:     private Optional<BulkWriter.Factory<RowData>> createBulkWriterFactory(
752:             String[] partitionColumns, StorageDescriptor sd) {
753:         String serLib = sd.getSerdeInfo().getSerializationLib().toLowerCase();
754:         int formatFieldCount = resolvedSchema.getColumns().size() - partitionColumns.length;
755:         String[] formatNames = new String[formatFieldCount];
756:         LogicalType[] formatTypes = new LogicalType[formatFieldCount];
757:         for (int i = 0; i < formatFieldCount; i++) {
758:             formatNames[i] = resolvedSchema.getColumnNames().get(i);
759:             formatTypes[i] = resolvedSchema.getColumnDataTypes().get(i).getLogicalType();
760:         }
761:         RowType formatType = RowType.of(formatTypes, formatNames);
762:         if (serLib.contains("parquet")) {
763:             Configuration formatConf = new Configuration(jobConf);
764:             sd.getSerdeInfo().getParameters().forEach(formatConf::set);
765:             return Optional.of(
766:                     ParquetRowDataBuilder.createWriterFactory(
767:                             formatType, formatConf, hiveVersion.startsWith("3.")));
768:         } else if (serLib.contains("orc")) {
769:             Configuration formatConf = new ThreadLocalClassLoaderConfiguration(jobConf);
770:             sd.getSerdeInfo().getParameters().forEach(formatConf::set);
771:             TypeDescription typeDescription = OrcSplitReaderUtil.logicalTypeToOrcType(formatType);
772:             return Optional.of(
773:                     hiveShim.createOrcBulkWriterFactory(
774:                             formatConf, typeDescription.toString(), formatTypes));
775:         } else {
776:             return Optional.empty();
777:         }
778:     }
