322:             boolean[] inputSortDirections) {
323:         if (inputType instanceof CompositeType) {
324:             return ((CompositeType<T>) inputType)
325:                     .createComparator(inputKeys, inputSortDirections, 0, executionConfig);
326:         } else if (inputType instanceof AtomicType) {
327:             return ((AtomicType<T>) inputType)
328:                     .createComparator(inputSortDirections[0], executionConfig);
329:         }
330: 
331:         throw new InvalidProgramException(
332:                 "Input type of coGroup must be one of composite types or atomic types.");
