360:                 TypeComparator<IN1> inputComparator1,
361:                 TypeSerializer<IN1> serializer1,
362:                 List<IN2> input2,
363:                 final TypeComparator<IN2> inputSortComparator2,
364:                 TypeComparator<IN2> inputComparator2,
365:                 TypeSerializer<IN2> serializer2) {
366:             this.pairComparator =
367:                     new GenericPairComparator<IN1, IN2>(inputComparator1, inputComparator2);
368: 
