335:     private static class CoGroupSortListIterator<IN1, IN2> {
336: 
337:         private static enum MatchStatus {
338:             NONE_REMAINED,
339:             FIRST_REMAINED,
340:             SECOND_REMAINED,
341:             FIRST_EMPTY,
342:             SECOND_EMPTY
343:         }
344: 
345:         private final ListKeyGroupedIterator<IN1> iterator1;
346: 
347:         private final ListKeyGroupedIterator<IN2> iterator2;
348: 
349:         private final TypePairComparator<IN1, IN2> pairComparator;
350: 
351:         private MatchStatus matchStatus;
352: 
353:         private Iterable<IN1> firstReturn;
354: 
355:         private Iterable<IN2> secondReturn;
356: 
357:         private CoGroupSortListIterator(
358:                 List<IN1> input1,
359:                 final TypeComparator<IN1> inputSortComparator1,
360:                 TypeComparator<IN1> inputComparator1,
361:                 TypeSerializer<IN1> serializer1,
362:                 List<IN2> input2,
363:                 final TypeComparator<IN2> inputSortComparator2,
364:                 TypeComparator<IN2> inputComparator2,
365:                 TypeSerializer<IN2> serializer2) {
366:             this.pairComparator =
367:                     new GenericPairComparator<IN1, IN2>(inputComparator1, inputComparator2);
368: 
369:             this.iterator1 = new ListKeyGroupedIterator<IN1>(input1, serializer1, inputComparator1);
370:             this.iterator2 = new ListKeyGroupedIterator<IN2>(input2, serializer2, inputComparator2);
371: 
372:             // ----------------------------------------------------------------
373:             // Sort
374:             // ----------------------------------------------------------------
375:             Collections.sort(
376:                     input1,
377:                     new Comparator<IN1>() {
378:                         @Override
379:                         public int compare(IN1 o1, IN1 o2) {
380:                             return inputSortComparator1.compare(o1, o2);
381:                         }
382:                     });
383: 
384:             Collections.sort(
385:                     input2,
386:                     new Comparator<IN2>() {
387:                         @Override
388:                         public int compare(IN2 o1, IN2 o2) {
389:                             return inputSortComparator2.compare(o1, o2);
390:                         }
391:                     });
392:         }
393: 
394:         private boolean next() throws IOException {
395:             boolean firstEmpty = true;
396:             boolean secondEmpty = true;
397: 
398:             if (this.matchStatus != MatchStatus.FIRST_EMPTY) {
399:                 if (this.matchStatus == MatchStatus.FIRST_REMAINED) {
400:                     // comparator is still set correctly
401:                     firstEmpty = false;
402:                 } else {
403:                     if (this.iterator1.nextKey()) {
404:                         this.pairComparator.setReference(iterator1.getValues().getCurrent());
405:                         firstEmpty = false;
406:                     }
407:                 }
408:             }
409: 
410:             if (this.matchStatus != MatchStatus.SECOND_EMPTY) {
411:                 if (this.matchStatus == MatchStatus.SECOND_REMAINED) {
412:                     secondEmpty = false;
413:                 } else {
414:                     if (iterator2.nextKey()) {
415:                         secondEmpty = false;
416:                     }
417:                 }
418:             }
419: 
420:             if (firstEmpty && secondEmpty) {
421:                 // both inputs are empty
422:                 return false;
423:             } else if (firstEmpty && !secondEmpty) {
424:                 // input1 is empty, input2 not
425:                 this.firstReturn = Collections.emptySet();
426:                 this.secondReturn = this.iterator2.getValues();
427:                 this.matchStatus = MatchStatus.FIRST_EMPTY;
428:                 return true;
429:             } else if (!firstEmpty && secondEmpty) {
430:                 // input1 is not empty, input 2 is empty
431:                 this.firstReturn = this.iterator1.getValues();
432:                 this.secondReturn = Collections.emptySet();
433:                 this.matchStatus = MatchStatus.SECOND_EMPTY;
434:                 return true;
435:             } else {
436:                 // both inputs are not empty
437:                 final int comp =
438:                         this.pairComparator.compareToReference(iterator2.getValues().getCurrent());
439: 
440:                 if (0 == comp) {
441:                     // keys match
442:                     this.firstReturn = this.iterator1.getValues();
443:                     this.secondReturn = this.iterator2.getValues();
444:                     this.matchStatus = MatchStatus.NONE_REMAINED;
445:                 } else if (0 < comp) {
446:                     // key1 goes first
447:                     this.firstReturn = this.iterator1.getValues();
448:                     this.secondReturn = Collections.emptySet();
449:                     this.matchStatus = MatchStatus.SECOND_REMAINED;
450:                 } else {
451:                     // key 2 goes first
452:                     this.firstReturn = Collections.emptySet();
453:                     this.secondReturn = this.iterator2.getValues();
454:                     this.matchStatus = MatchStatus.FIRST_REMAINED;
455:                 }
456:                 return true;
457:             }
458:         }
459: 
460:         private Iterable<IN1> getValues1() {
461:             return firstReturn;
462:         }
463: 
464:         private Iterable<IN2> getValues2() {
465:             return secondReturn;
466:         }
467:     }
468: }
