236:     @SuppressWarnings("unchecked")
237:     protected void executeOnCollections(
238:             List<IN> inputData, RuntimeContext ctx, ExecutionConfig executionConfig)
239:             throws Exception {
240:         OutputFormat<IN> format = this.formatWrapper.getUserCodeObject();
241:         TypeInformation<IN> inputType = getInput().getOperatorInfo().getOutputType();
242: 
243:         if (this.localOrdering != null) {
244:             int[] sortColumns = this.localOrdering.getFieldPositions();
245:             boolean[] sortOrderings = this.localOrdering.getFieldSortDirections();
246: 
247:             final TypeComparator<IN> sortComparator;
248:             if (inputType instanceof CompositeType) {
249:                 sortComparator =
250:                         ((CompositeType<IN>) inputType)
251:                                 .createComparator(sortColumns, sortOrderings, 0, executionConfig);
252:             } else if (inputType instanceof AtomicType) {
253:                 sortComparator =
254:                         ((AtomicType<IN>) inputType)
255:                                 .createComparator(sortOrderings[0], executionConfig);
256:             } else {
257:                 throw new UnsupportedOperationException(
258:                         "Local output sorting does not support type " + inputType + " yet.");
259:             }
260: 
261:             Collections.sort(
262:                     inputData,
263:                     new Comparator<IN>() {
264:                         @Override
265:                         public int compare(IN o1, IN o2) {
266:                             return sortComparator.compare(o1, o2);
267:                         }
268:                     });
269:         }
270: 
271:         if (format instanceof InitializeOnMaster) {
272:             ((InitializeOnMaster) format).initializeGlobal(1);
273:         }
274:         format.configure(this.parameters);
275: 
276:         if (format instanceof RichOutputFormat) {
277:             ((RichOutputFormat<?>) format).setRuntimeContext(ctx);
278:         }
279:         format.open(0, 1);
280:         for (IN element : inputData) {
281:             format.writeRecord(element);
282:         }
283: 
284:         format.close();
285: 
286:         if (format instanceof FinalizeOnMaster) {
287:             ((FinalizeOnMaster) format).finalizeGlobal(1);
288:         }
289:     }
