65: /**
66:  * The post-optimizer plan traversal. This traversal fills in the API specific utilities
67:  * (serializers and comparators).
68:  */
69: public class JavaApiPostPass implements OptimizerPostPass {
70: 
71:     private final Set<PlanNode> alreadyDone = new HashSet<PlanNode>();
72: 
73:     private ExecutionConfig executionConfig = null;
74: 
75:     @Override
76:     public void postPass(OptimizedPlan plan) {
77: 
78:         executionConfig = plan.getOriginalPlan().getExecutionConfig();
79: 
80:         for (SinkPlanNode sink : plan.getDataSinks()) {
81:             traverse(sink);
82:         }
83:     }
84: 
85:     protected void traverse(PlanNode node) {
86:         if (!alreadyDone.add(node)) {
87:             // already worked on that one
88:             return;
89:         }
90: 
91:         // distinguish the node types
92:         if (node instanceof SinkPlanNode) {
93:             // descend to the input channel
94:             SinkPlanNode sn = (SinkPlanNode) node;
95:             Channel inchannel = sn.getInput();
96:             traverseChannel(inchannel);
97:         } else if (node instanceof SourcePlanNode) {
98:             TypeInformation<?> typeInfo = getTypeInfoFromSource((SourcePlanNode) node);
99:             ((SourcePlanNode) node).setSerializer(createSerializer(typeInfo));
100:         } else if (node instanceof BulkIterationPlanNode) {
101:             BulkIterationPlanNode iterationNode = (BulkIterationPlanNode) node;
102: 
103:             if (iterationNode.getRootOfStepFunction() instanceof NAryUnionPlanNode) {
104:                 throw new CompilerException(
105:                         "Optimizer cannot compile an iteration step function where next partial solution is created by a Union node.");
106:             }
107: 
108:             // traverse the termination criterion for the first time. create schema only, no
109:             // utilities. Needed in case of intermediate termination criterion
110:             if (iterationNode.getRootOfTerminationCriterion() != null) {
111:                 SingleInputPlanNode addMapper =
112:                         (SingleInputPlanNode) iterationNode.getRootOfTerminationCriterion();
113:                 traverseChannel(addMapper.getInput());
114:             }
115: 
116:             BulkIterationBase<?> operator =
117:                     (BulkIterationBase<?>) iterationNode.getProgramOperator();
118: 
119:             // set the serializer
120:             iterationNode.setSerializerForIterationChannel(
121:                     createSerializer(operator.getOperatorInfo().getOutputType()));
122: 
123:             // done, we can now propagate our info down
124:             traverseChannel(iterationNode.getInput());
125:             traverse(iterationNode.getRootOfStepFunction());
126:         } else if (node instanceof WorksetIterationPlanNode) {
127:             WorksetIterationPlanNode iterationNode = (WorksetIterationPlanNode) node;
128: 
129:             if (iterationNode.getNextWorkSetPlanNode() instanceof NAryUnionPlanNode) {
130:                 throw new CompilerException(
131:                         "Optimizer cannot compile a workset iteration step function where the next workset is produced by a Union node.");
132:             }
133:             if (iterationNode.getSolutionSetDeltaPlanNode() instanceof NAryUnionPlanNode) {
134:                 throw new CompilerException(
135:                         "Optimizer cannot compile a workset iteration step function where the solution set delta is produced by a Union node.");
136:             }
137: 
138:             DeltaIterationBase<?, ?> operator =
139:                     (DeltaIterationBase<?, ?>) iterationNode.getProgramOperator();
140: 
141:             // set the serializers and comparators for the workset iteration
142:             iterationNode.setSolutionSetSerializer(
143:                     createSerializer(operator.getOperatorInfo().getFirstInputType()));
144:             iterationNode.setWorksetSerializer(
145:                     createSerializer(operator.getOperatorInfo().getSecondInputType()));
146:             iterationNode.setSolutionSetComparator(
147:                     createComparator(
148:                             operator.getOperatorInfo().getFirstInputType(),
149:                             iterationNode.getSolutionSetKeyFields(),
150:                             getSortOrders(iterationNode.getSolutionSetKeyFields(), null)));
151: 
152:             // traverse the inputs
153:             traverseChannel(iterationNode.getInput1());
154:             traverseChannel(iterationNode.getInput2());
155: 
156:             // traverse the step function
157:             traverse(iterationNode.getSolutionSetDeltaPlanNode());
158:             traverse(iterationNode.getNextWorkSetPlanNode());
159:         } else if (node instanceof SingleInputPlanNode) {
160:             SingleInputPlanNode sn = (SingleInputPlanNode) node;
161: 
162:             if (!(sn.getOptimizerNode().getOperator() instanceof SingleInputOperator)) {
163: 
164:                 // Special case for delta iterations
165:                 if (sn.getOptimizerNode().getOperator() instanceof NoOpUnaryUdfOp) {
166:                     traverseChannel(sn.getInput());
167:                     return;
168:                 } else {
169:                     throw new RuntimeException("Wrong operator type found in post pass.");
170:                 }
171:             }
172: 
173:             SingleInputOperator<?, ?, ?> singleInputOperator =
174:                     (SingleInputOperator<?, ?, ?>) sn.getOptimizerNode().getOperator();
175: 
176:             // parameterize the node's driver strategy
177:             for (int i = 0; i < sn.getDriverStrategy().getNumRequiredComparators(); i++) {
178:                 sn.setComparator(
179:                         createComparator(
180:                                 singleInputOperator.getOperatorInfo().getInputType(),
181:                                 sn.getKeys(i),
182:                                 getSortOrders(sn.getKeys(i), sn.getSortOrders(i))),
183:                         i);
184:             }
185:             // done, we can now propagate our info down
186:             traverseChannel(sn.getInput());
187: 
188:             // don't forget the broadcast inputs
189:             for (Channel c : sn.getBroadcastInputs()) {
190:                 traverseChannel(c);
191:             }
192:         } else if (node instanceof DualInputPlanNode) {
193:             DualInputPlanNode dn = (DualInputPlanNode) node;
194: 
195:             if (!(dn.getOptimizerNode().getOperator() instanceof DualInputOperator)) {
196:                 throw new RuntimeException("Wrong operator type found in post pass.");
197:             }
198: 
199:             DualInputOperator<?, ?, ?, ?> dualInputOperator =
200:                     (DualInputOperator<?, ?, ?, ?>) dn.getOptimizerNode().getOperator();
201: 
202:             // parameterize the node's driver strategy
203:             if (dn.getDriverStrategy().getNumRequiredComparators() > 0) {
204:                 dn.setComparator1(
205:                         createComparator(
206:                                 dualInputOperator.getOperatorInfo().getFirstInputType(),
207:                                 dn.getKeysForInput1(),
208:                                 getSortOrders(dn.getKeysForInput1(), dn.getSortOrders())));
209:                 dn.setComparator2(
210:                         createComparator(
211:                                 dualInputOperator.getOperatorInfo().getSecondInputType(),
212:                                 dn.getKeysForInput2(),
213:                                 getSortOrders(dn.getKeysForInput2(), dn.getSortOrders())));
214: 
215:                 dn.setPairComparator(
216:                         createPairComparator(
217:                                 dualInputOperator.getOperatorInfo().getFirstInputType(),
218:                                 dualInputOperator.getOperatorInfo().getSecondInputType()));
219:             }
220: 
221:             traverseChannel(dn.getInput1());
222:             traverseChannel(dn.getInput2());
223: 
224:             // don't forget the broadcast inputs
225:             for (Channel c : dn.getBroadcastInputs()) {
226:                 traverseChannel(c);
227:             }
228: 
229:         }
230:         // catch the sources of the iterative step functions
231:         else if (node instanceof BulkPartialSolutionPlanNode
232:                 || node instanceof SolutionSetPlanNode
233:                 || node instanceof WorksetPlanNode) {
234:             // Do nothing :D
235:         } else if (node instanceof NAryUnionPlanNode) {
236:             // Traverse to all child channels
237:             for (Channel channel : node.getInputs()) {
238:                 traverseChannel(channel);
239:             }
240:         } else {
241:             throw new CompilerPostPassException(
242:                     "Unknown node type encountered: " + node.getClass().getName());
243:         }
244:     }
245: 
246:     private void traverseChannel(Channel channel) {
247: 
248:         PlanNode source = channel.getSource();
249:         Operator<?> javaOp = source.getProgramOperator();
250: 
251:         //		if (!(javaOp instanceof BulkIteration) && !(javaOp instanceof JavaPlanNode)) {
252:         //			throw new RuntimeException("Wrong operator type found in post pass: " + javaOp);
253:         //		}
254: 
255:         TypeInformation<?> type = javaOp.getOperatorInfo().getOutputType();
256: 
257:         if (javaOp instanceof GroupReduceOperatorBase
258:                 && (source.getDriverStrategy() == DriverStrategy.SORTED_GROUP_COMBINE
259:                         || source.getDriverStrategy() == DriverStrategy.ALL_GROUP_REDUCE_COMBINE)) {
260:             GroupReduceOperatorBase<?, ?, ?> groupNode = (GroupReduceOperatorBase<?, ?, ?>) javaOp;
261:             type = groupNode.getInput().getOperatorInfo().getOutputType();
262:         } else if (javaOp instanceof PlanUnwrappingReduceGroupOperator
263:                 && source.getDriverStrategy().equals(DriverStrategy.SORTED_GROUP_COMBINE)) {
264:             PlanUnwrappingReduceGroupOperator<?, ?, ?> groupNode =
265:                     (PlanUnwrappingReduceGroupOperator<?, ?, ?>) javaOp;
266:             type = groupNode.getInput().getOperatorInfo().getOutputType();
267:         }
268: 
269:         // the serializer always exists
270:         channel.setSerializer(createSerializer(type));
271: 
272:         // parameterize the ship strategy
273:         if (channel.getShipStrategy().requiresComparator()) {
274:             channel.setShipStrategyComparator(
275:                     createComparator(
276:                             type,
277:                             channel.getShipStrategyKeys(),
278:                             getSortOrders(
279:                                     channel.getShipStrategyKeys(),
280:                                     channel.getShipStrategySortOrder())));
281:         }
282: 
283:         // parameterize the local strategy
284:         if (channel.getLocalStrategy().requiresComparator()) {
285:             channel.setLocalStrategyComparator(
286:                     createComparator(
287:                             type,
288:                             channel.getLocalStrategyKeys(),
289:                             getSortOrders(
290:                                     channel.getLocalStrategyKeys(),
291:                                     channel.getLocalStrategySortOrder())));
292:         }
293: 
294:         // descend to the channel's source
295:         traverse(channel.getSource());
296:     }
