298:     @SuppressWarnings("unchecked")
299:     private static <T> TypeInformation<T> getTypeInfoFromSource(SourcePlanNode node) {
300:         Operator<?> op = node.getOptimizerNode().getOperator();
301: 
302:         if (op instanceof GenericDataSourceBase) {
303:             return ((GenericDataSourceBase<T, ?>) op).getOperatorInfo().getOutputType();
304:         } else {
305:             throw new RuntimeException("Wrong operator type found in post pass.");
306:         }
307:     }
308: 
309:     private <T> TypeSerializerFactory<?> createSerializer(TypeInformation<T> typeInfo) {
310:         TypeSerializer<T> serializer = typeInfo.createSerializer(executionConfig);
311: 
312:         return new RuntimeSerializerFactory<T>(serializer, typeInfo.getTypeClass());
313:     }
314: 
315:     @SuppressWarnings("unchecked")
316:     private <T> TypeComparatorFactory<?> createComparator(
317:             TypeInformation<T> typeInfo, FieldList keys, boolean[] sortOrder) {
318: 
319:         TypeComparator<T> comparator;
320:         if (typeInfo instanceof CompositeType) {
321:             comparator =
322:                     ((CompositeType<T>) typeInfo)
323:                             .createComparator(keys.toArray(), sortOrder, 0, executionConfig);
324:         } else if (typeInfo instanceof AtomicType) {
325:             // handle grouping of atomic types
326:             comparator = ((AtomicType<T>) typeInfo).createComparator(sortOrder[0], executionConfig);
327:         } else {
328:             throw new RuntimeException("Unrecognized type: " + typeInfo);
329:         }
330: 
331:         return new RuntimeComparatorFactory<T>(comparator);
332:     }
333: 
334:     private static <T1 extends Tuple, T2 extends Tuple>
335:             TypePairComparatorFactory<T1, T2> createPairComparator(
336:                     TypeInformation<?> typeInfo1, TypeInformation<?> typeInfo2) {
337:         //		@SuppressWarnings("unchecked")
338:         //		TupleTypeInfo<T1> info1 = (TupleTypeInfo<T1>) typeInfo1;
339:         //		@SuppressWarnings("unchecked")
340:         //		TupleTypeInfo<T2> info2 = (TupleTypeInfo<T2>) typeInfo2;
341: 
342:         return new RuntimePairComparatorFactory<T1, T2>();
343:     }
344: 
345:     private static final boolean[] getSortOrders(FieldList keys, boolean[] orders) {
346:         if (orders == null) {
347:             orders = new boolean[keys.size()];
348:             Arrays.fill(orders, true);
349:         }
350:         return orders;
351:     }
352: }
